// Run after `yarn build`: node --test tests/quest-plugins.test.cjs
const assert = require('node:assert/strict');
const { test, before } = require('node:test');
const { Server } = require('../dist/Server');
Server.installProductionPathResolver();
before(async () => {
  await require('../dist/game/cache/CachePipeline').CachePipeline.initialize(require('node:path').resolve(__dirname, '..'));
  require('../dist/game/collision/RegionManager').RegionManager.init();
});

const { PluginManager } = require('../dist/plugins/PluginManager');
const apiMethods = new Set(Object.keys(PluginManager.createApi('QuestTest')));
const noopPacketSender = new Proxy({}, { get: (_target, key) => key === 'getVarbit' ? () => 0 : () => noopPacketSender });

test('quest event names register and dispatch through the production API', () => {
  const fs = require('node:fs');
  const path = require('node:path');
  const root = path.resolve(__dirname, '../plugins/quests');
  const events = new Map();
  function scan(directory) {
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
      const file = path.join(directory, entry.name);
      if (entry.isDirectory()) scan(file);
      else if (entry.name.endsWith('.js')) {
        const source = fs.readFileSync(file, 'utf8');
        const constants = new Map([...source.matchAll(/\bconst\s+(\w+)\s*=\s*(['"])([^'"]+)\2/g)]
          .map((match) => [match[1], match[3]]));
        for (const match of source.matchAll(/\b(?:onCustomEvent|emitCustomEvent)(?:\?\.)?\s*\(\s*(['"])([^'"]+)\1/g)) {
          events.set(match[2], file);
        }
        for (const match of source.matchAll(/\b(?:onCustomEvent|emitCustomEvent)(?:\?\.)?\s*\(\s*(\w+)\s*[,)]/g)) {
          if (constants.has(match[1])) events.set(constants.get(match[1]), file);
        }
      }
    }
  }
  scan(root);
  const api = PluginManager.createApi('QuestEventContract');
  for (const [name, file] of events) {
    const previous = PluginManager.customEventHooks.get(name);
    let received = null;
    const payload = {};
    try {
      PluginManager.customEventHooks.delete(name);
      api.onCustomEvent(name, (event) => { received = event; });
      api.emitCustomEvent(name, payload);
      assert.equal(received, payload, `${path.relative(root, file)}: rejected event ${name}`);
    } finally {
      if (previous) PluginManager.customEventHooks.set(name, previous);
      else PluginManager.customEventHooks.delete(name);
    }
  }
});

// A stand-in for the live PluginApi: real core, every hook a no-op. Quests must
// register cleanly through it and hand back their variant/condition resolvers.
function mockApi() {
  const objects = [];
  const routes = [];
  const npcInteractions = new Map();
  const handlers = {
    variant: [],
    condition: [],
    custom: new Map(),
    namedObjects: [],
    npcInteractions,
    npc: npcInteractions,
    area: [],
    ground: [],
    namedItemActions: new Map(),
    objects,
    object: objects,
    itemOnItem: [],
    itemOnNpc: [],
    itemOnObject: [],
    itemAction: [],
    routes,
    route: routes,
    walkRoutes: [],
    playerProcess: [],
    playerMapSquareChange: [],
    playerLogin: [],
    playerLogout: [],
    playerBeforeDeath: [],
    npcBeforeDeath: [],
    npcDeath: [],
    npcHitModify: [],
    combatHitRoll: [],
    canBankItem: [],
  };
  const noop = () => {};
  const base = {
    core: PluginManager.getCoreApi(),
    onNpcDialogueVariant: (h) => handlers.variant.push(h),
    onNpcDialogueCondition: (h) => handlers.condition.push(h),
    onObjectInteraction: (target, actions) => {
      if (typeof target === 'function') return handlers.objects.push(target);
      handlers.namedObjects.push({ target, actions });
      for (const [option, handler] of Object.entries(actions)) handlers.objects.push(event => {
        if (event.definition?.getName?.() === target && event.option === option) return handler(event);
        return false;
      });
    },
    onNpcInteraction: (target, actions) => { assert(['string', 'function'].includes(typeof target), 'NPC hooks accept names or generic handlers'); handlers.npcInteractions.set(target, actions); },
    onObjectRoute: (h) => handlers.routes.push(h),
    onWalkRoute: (h) => handlers.walkRoutes.push(h),
    onPlayerProcess: (h) => handlers.playerProcess.push(h),
    onPlayerMapSquareChange: (h) => handlers.playerMapSquareChange.push(h),
    onPlayerLogin: (h) => handlers.playerLogin.push(h),
    onPlayerLogout: (h) => handlers.playerLogout.push(h),
    onPlayerBeforeDeath: h => handlers.playerBeforeDeath.push(h),
    onNpcBeforeDeath: h => handlers.npcBeforeDeath.push(h),
    onNpcDeath: h => handlers.npcDeath.push(h),
    onNpcHitModify: (h) => handlers.npcHitModify.push(h),
    onCombatHitRoll: h => handlers.combatHitRoll.push(h),
    onCanBankItem: h => handlers.canBankItem.push(h),
    onItemOnItem: (h) => handlers.itemOnItem.push(h),
    onItemOnNpc: (h) => handlers.itemOnNpc.push(h),
    onItemOnObject: (...args) => handlers.itemOnObject.push(typeof args[0] === 'function' ? args[0] : args[2]),
    onItemAction: (...args) => {
      handlers.itemAction.push(args.at(-1));
      if (typeof args[0] === 'string') handlers.namedItemActions.set(args[0], args[1]);
    },
    registerArea: area => handlers.area.push(area),
    onGroundItemPickup: handler => handlers.ground.push(handler),
    onCustomEvent: (name, h) => {
      assert.match(name, /^[^:]+:[^:]+$/, 'custom event names must have exactly one colon');
      const list = handlers.custom.get(name) ?? [];
      list.push(h);
      handlers.custom.set(name, list);
    },
    emitCustomEvent: (name, event) => {
      assert.match(name, /^[^:]+:[^:]+$/, 'custom event names must have exactly one colon');
      for (const handler of handlers.custom.get(name) ?? []) handler(event);
    },
    persistAttribute: noop,
  };
  const api = new Proxy(base, {
    get(target, prop) {
      if (prop in target) return target[prop];
      if (apiMethods.has(prop)) return noop;
      throw Error('Unknown PluginApi member: '+String(prop));

    },
  });
  return { api, handlers };
}

test('Quests.plugin registers every quest through api.core without throwing', () => {
  const { api } = mockApi();
  const plugin = require('../plugins/quests/Quests.plugin');
  assert.equal(plugin.name, 'Quests');
  assert.doesNotThrow(() => plugin.register(api));
});

test('Lost City only warns about low combat when a starting skill is also missing', () => {
  const { api, handlers } = mockApi();
  require('../plugins/quests/quests/LostCity.Quest')(api);
  const condition = handlers.condition.at(-1);
  const playerAt = (combat, crafting, woodcutting) => ({
    getSkillManager: () => ({
      getCombatLevel: () => combat,
      getMaxLevel: skill => skill === api.core.Skill.CRAFTING ? crafting
        : skill === api.core.Skill.WOODCUTTING ? woodcutting : 1,
    }),
  });
  const text = 'If the player has lower than 45 combat and either 31 Crafting or 36 Woodcutting:';
  assert.equal(condition({ player: playerAt(126, 1, 1), text }), false,
    'a high-combat player missing both skills must not receive the low-combat warning');
  assert.equal(condition({ player: playerAt(40, 1, 1), text }), true,
    'the combined warning applies when combat and a skill are both below the requirement');
  assert.equal(condition({ player: playerAt(40, 31, 36), text }), false,
    'meeting both skill requirements suppresses the warning');
});

test('Family Crest only handles gold rocks in Witchaven and Mining recognizes the shared gold-rock object', () => {
  const { api, handlers } = mockApi();
  require('../plugins/quests/quests/FamilyCrest.Quest')(api);
  const handleObjectInteraction = handlers.objects.at(-1);
  const messages = [];
  const player = { getAttribute: () => 0, sendMessage: message => messages.push(message) };
  const interact = (x, y, z) => {
    const event = {
      player,
      objectId: api.core.ObjectIdentifiers.GOLD_ROCKS_2,
      clickType: 1,
      definition: { getInteractions: () => ['Mine'] },
      location: { x, y, z },
      handled: false,
    };
    handleObjectInteraction(event);
    return event;
  };

  assert.equal(interact(2933, 3288, 0).handled, false, 'Crafting Guild rocks must be left to Mining');
  const witchavenRock = interact(2732, 9680, 0);
  assert.equal(witchavenRock.handled, true, 'Witchaven rocks retain the Family Crest interaction');
  assert.equal(messages.at(-1), 'This gold does not look special to you.');

  const { ROCKS } = require('../plugins/skills/Mining.plugin');
  const { GOLD_ROCKS_2 } = api.core.ObjectIdentifiers;
  assert.ok(ROCKS.find(rock => rock.objectName === 'Gold rocks').objectIds.includes(GOLD_ROCKS_2));
});

test('a shop version named after a quest opens once its quest state matches (#831)', () => {
  const { api } = mockApi();
  require('../plugins/quests/Quests.plugin').register(api);
  const { getRegisteredQuests, pickQuestShopVersion } = require('../plugins/quests/QuestRuntime');
  const named = (name) => getRegisteredQuests().find((quest) => quest.name === name);
  const attributes = new Map();
  const player = {
    getAttribute: (key) => attributes.get(key),
    setAttribute: (key, value) => attributes.set(key, value),
    getPacketSender: () => new Proxy({}, { get: () => () => {} }),
  };
  const pick = (shops) => {
    const request = { player, shops, shop: null };
    pickQuestShopVersion(request);
    return request.shop;
  };
  const ned = ["Ned's Handmade Rope (100% Wool) (Default)", "Ned's Handmade Rope (100% Wool) (Fremennik Isles)"];
  const babaYaga = ["Baba Yaga's Magic Shop. (After Lunar Diplomacy)", "Baba Yaga's Magic Shop. (During Lunar Diplomacy)"];
  assert.equal(pick(ned), null, 'Default and Karamja gloves versions are left to the dialogue runtime');
  assert.equal(pick(babaYaga), null);
  const isles = named('The Fremennik Isles');
  isles.setStage(player, isles.completionValue ?? 2);
  assert.equal(pick(ned), ned[1], '"Fremennik Isles" names The Fremennik Isles');
  const lunar = named('Lunar Diplomacy');
  lunar.setStage(player, lunar.startedValue ?? 1);
  assert.equal(pick(babaYaga), babaYaga[1]);
  lunar.setStage(player, lunar.completionValue ?? 2);
  assert.equal(pick(babaYaga), babaYaga[0]);
});

test('DT2 medallions cannot be banked while ordinary items remain bankable', () => {
  const { api, handlers } = mockApi();
  require('../plugins/quests/quests/DesertTreasureII.Quest')(api);
  assert.equal(handlers.canBankItem.length, 1);
  const ids = api.core.ItemIdentifiers;
  const player = { messages: [], sendMessage(message) { this.messages.push(message); } };
  for (const id of [ids.VARDORVIS_MEDALLION, ids.PERSERIYAS_MEDALLION, ids.SUCELLUS_MEDALLION, ids.WHISPERERS_MEDALLION]) {
    const event = { player, item: new api.core.Item(id), allow: null };
    handlers.canBankItem[0](event);
    assert.equal(event.allow, false, `medallion ${id} should remain outside the bank`);
  }
  const rune = { player, item: new api.core.Item(ids.AIR_RUNE), allow: null };
  handlers.canBankItem[0](rune);
  assert.equal(rune.allow, null, 'ordinary items keep the normal bank policy');
  assert.equal(player.messages.length, 4);
});

test('completed Desert Treasure I players can ask Rasolo for a replacement Ring of Visibility', () => {
  const { api, handlers } = mockApi();
  require('../plugins/quests/quests/DesertTreasureI.Quest')(api);
  const ring = api.core.ItemIdentifiers.RING_OF_VISIBILITY;
  const items = new Map();
  let full = false;
  let banks = [];
  const player = {
    getAttribute: key => key === 'quest.desert_treasure_i.stage' ? 15 : undefined,
    getInventory: () => ({
      getAmount: id => items.get(id) ?? 0,
      adds: (id, amount) => items.set(id, (items.get(id) ?? 0) + amount),
      isFull: () => full,
    }),
    getEquipment: () => ({ get: () => null }),
    getBanks: () => banks,
    sendMessage() {},
  };

  assert.equal(handlers.variant.at(-1)({ player, npcId: api.core.NpcIdentifiers.RASOLO }), 'standard-dialogue-after-desert-treasure-i');
  const dialogue = require('../data/definitions/npc-dialogues.json').Rasolo.variants['standard-dialogue-after-desert-treasure-i'];
  assert.ok(dialogue[1].options.some(option => option.text === 'I lost that ring you gave me...'));

  const condition = handlers.condition.at(-1);
  assert.equal(condition({ player, npcId: api.core.NpcIdentifiers.RASOLO, text: 'If the player has a Ring of visibility in their inventory or bank:' }), false);
  assert.equal(condition({ player, npcId: api.core.NpcIdentifiers.RASOLO, text: 'If the player does not have a Ring of visibility in their inventory or bank, and their inventory is full:' }), false);
  assert.equal(condition({ player, npcId: api.core.NpcIdentifiers.RASOLO, text: 'If the player does not have a Ring of visibility in their inventory or bank, and has inventory space:' }), true);
  const reward = { player, npcId: api.core.NpcIdentifiers.RASOLO, stepId: 'RdQo2r', handled: false };
  api.emitCustomEvent('npc-dialogue:action', reward);
  assert.equal(reward.handled, true);
  assert.equal(items.get(ring), 1);

  banks = [{ contains: id => id === ring }];
  assert.equal(condition({ player, npcId: api.core.NpcIdentifiers.RASOLO, text: 'If the player has a Ring of visibility in their inventory or bank:' }), true);
  assert.equal(condition({ player, npcId: api.core.NpcIdentifiers.RASOLO, text: 'If the player does not have a Ring of visibility in their inventory or bank, and has inventory space:' }), false);
});

test('NPC Contact paginates plugin contacts and dispatches the chosen contact once', () => {
  const { LunarSpells } = require('../dist/game/content/combat/magic/LunarSpells');
  const original = PluginManager.emitCustomEvent;
  const contacts = ['Nieve', 'Duradel', 'Konar quo Maten', 'Mazchna', 'Turael', 'Cyrisus'];
  let chain;
  const dispatched = [];
  const player = {
    getDialogueManager: () => ({ startDialogues: builder => { chain = builder; } }),
    getPacketSender: () => ({ sendInterfaceRemoval() {} }),
    sendMessage: message => { throw Error(message); },
  };
  PluginManager.emitCustomEvent = (name, event) => {
    if (name === 'magic:npc-contact') event.contacts.push(...contacts.slice(4));
    else { dispatched.push(event.name); event.handled = true; }
  };
  try {
    LunarSpells.openNpcContact(player);
    let menu = [...chain.getDialogues().values()][0];
    assert.equal(menu.getOptions().length, 5);
    menu.execute(5);
    menu = [...chain.getDialogues().values()][0];
    assert.deepEqual(menu.getOptions(), ['Turael', 'Cyrisus']);
    menu.execute(2);
    assert.deepEqual(dispatched, ['Cyrisus']);
  } finally { PluginManager.emitCustomEvent = original; }
});

test('Blood Moon refinery handoff uses valid events, restores the tomb route, and waits for escape', () => {
  const { api, handlers } = mockApi();
  const moveCalls = [], varbits = [], completions = [];
  const attrs = new Map();
  const player = {
    getAttribute: key => attrs.get(key),
    setAttribute: (key, value) => attrs.set(key, value),
    getPacketSender: () => ({ sendVarbit: (id, value) => varbits.push([id, value]), sendQuestList() {},
      sendInterfaceFlagsRange() {}, sendConfig() {} }),
    getLocation: () => new api.core.Location(3417, 3487, 1),
    moveTo: location => moveCalls.push(location),
  };
  api.onCustomEvent('test:completed', event => completions.push(event.player));
  const refinery = require('../plugins/quests/bmr/Refinery.TheBloodMoonRises')(api);
  const eventNames = [...handlers.custom.keys()].filter(name => name.startsWith('bmr:'));
  assert.deepEqual(eventNames, ['bmr:refinery-start']);
  assert.ok(eventNames.every(name => /^[^:\s]+:[^:\s]+$/.test(name)), 'the server dispatches only one-colon event names');
  attrs.set('quest.the_blood_moon_rises.slepe-story', { tombRouteStarted: true });
  handlers.playerLogin.at(-1)({ player });
  assert.deepEqual(moveCalls, [], 'the handoff begins the tomb route without teleporting the player');
  assert.equal(attrs.get('the-blood-moon-rises:refinery-progress').phase, 'route');
  assert.deepEqual(varbits.at(-1), [15464, 48]);
  assert.ok([...handlers.custom.keys()].includes('bmr:refinery-start'));

  const emitted = [];
  api.emitCustomEvent = (name, event) => {
    emitted.push(name);
    if (name === 'bmr:refinery-completed') completions.push(event.player);
  };
  refinery.action({ player, stepId: 'jYDLQy' });
  assert.deepEqual(completions, [], 'the escape dialogue cannot complete before the owned room is cleared');
  attrs.set('the-blood-moon-rises:refinery-progress', { started: true, phase: 'cleared', killed: [0, 1, 2, 3, 4] });
  refinery.action({ player, stepId: 'jYDLQy' });
  refinery.action({ player, stepId: 'jYDLQy' });
  assert.deepEqual(completions, [player], 'the transcript action emits the handoff once');
  assert.ok(emitted.every(name => /^[^:\s]+:[^:\s]+$/.test(name)));
  assert.equal(attrs.get('the-blood-moon-rises:refinery-progress').phase, 'freed');
  assert.deepEqual(varbits.at(-1), [15464, 62]);
});

test('Blood Moon refinery phase varbit stops overriding the Castle Escape stage', () => {
  const { api, handlers } = mockApi();
  const vars = [], attrs = new Map([
    ['the-blood-moon-rises:refinery-progress', { started: true, phase: 'escaped', killed: [0, 1, 2, 3, 4] }],
  ]);
  let questStage = 45;
  const player = {
    getAttribute: key => attrs.get(key), setAttribute: (key, value) => attrs.set(key, value),
    getPacketSender: () => ({ sendVarbit: (id, value) => vars.push([id, value]) }),
    getLocation: () => new api.core.Location(2535, 7384, 0),
  };
  const refinery = require('../plugins/quests/bmr/Refinery.TheBloodMoonRises')(api, () => questStage);
  refinery.syncLogin({ player });
  const stageChanged = handlers.custom.get('quest:stage-changed').at(-1);
  stageChanged({ key: 'the_blood_moon_rises', stage: 45, player });
  assert.deepEqual(vars, [], 'saved refinery stage 64 cannot overwrite the later Castle stage 45');

  questStage = 30;
  stageChanged({ key: 'the_blood_moon_rises', stage: 30, player });
  assert.deepEqual(vars, [[15464, 64]], 'the refinery phase still restores while the quest is in Slepe');
});

test('Blood Moon refinery copies its exact cache room into a walkable four-plane scene', () => {
  const { api } = mockApi();
  const refinery = require('../plugins/quests/bmr/Refinery.TheBloodMoonRises')(api);
  const area = new refinery.RefineryArea({});
  const { RegionManager } = require('../dist/game/collision/RegionManager');
  try {
    for (let plane = 0; plane < 4; plane++) {
      assert.deepEqual(area.getChunk(plane, 4, 5), {
        sourceChunkX: 396, sourceChunkY: 933, sourcePlane: plane, rotation: 0,
      });
    }
    const entry = area.tile(3169 - 3136, 7456 - 7424, 0);
    assert.equal(RegionManager.getClipping(entry.getX(), entry.getY(), 0, area) & RegionManager.BLOCKED_TILE, 0);
    assert.deepEqual(refinery.sourceTile(area, { x: entry.getX(), y: entry.getY(), z: 0 }),
      { x: 3169, y: 7456, z: 0 }, 'plugin object packets use plain coordinates in the allocated scene');
    const reachable = new Set([`${entry.getX()},${entry.getY()}`]);
    const queue = [entry];
    for (let index = 0; index < queue.length; index++) {
      const tile = queue[index];
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const x = tile.getX() + dx, y = tile.getY() + dy, key = `${x},${y}`;
        if (reachable.has(key) || !RegionManager.canMove(tile.getX(), tile.getY(), x, y, 0, 1, 1, area)) continue;
        reachable.add(key);
        queue.push(area.tile(x - area.getBaseX(), y - area.getBaseY(), 0));
      }
    }
    for (const [, x, y] of refinery.ENEMIES) {
      const enemy = area.tile(x - 3136, y - 7424, 0);
      assert.equal(RegionManager.getClipping(enemy.getX(), enemy.getY(), 0, area) & RegionManager.BLOCKED_TILE, 0,
        `enemy anchor ${x},${y} uses walkable template floor`);
      assert.ok(reachable.has(`${enemy.getX()},${enemy.getY()}`), `enemy anchor ${x},${y} is reachable from the tunnel`);
    }
    assert.ok(reachable.size > refinery.ENEMIES.length, 'BFS follows the connected source-room floor copied into the private scene');
    const { CacheDefinitions } = require('../dist/game/cache/CacheDefinitions');
    const { ObjectIdentifiers: O } = api.core;
    const exit = CacheDefinitions.getObject(61203);
    assert.equal(exit.transformVarbit, 15464);
    assert.equal(exit.transforms[61], O.ENTRY_27, 'the freed-slaves native phase reveals the north exit');
    assert.equal(CacheDefinitions.getObject(O.ENTRY_27).actions[0], 'Enter');
  } finally {
    area.destroy();
  }
});

