test('Blood Moon resumes the completed Castle escape from its stranded stockpile save', () => {
  const { api, handlers } = mockApi();
  const spawned = [];
  api.spawnNpc = spec => { const npc = { ...spec, setScriptedMovement() {}, isDestroyed: () => false }; spawned.push(npc); return npc; };
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const { getRegisteredQuests } = require('../plugins/quests/QuestRuntime');
  const quest = getRegisteredQuests().filter(entry => entry.key === 'the_blood_moon_rises').at(-1);
  const attributes = new Map([
    ['quest.the_blood_moon_rises.stage', 45],
    ['quest.the_blood_moon_rises.castle-room', 43],
    ['quest.the_blood_moon_rises.castle-native-stage', 82],
    ['quest.the_blood_moon_rises.castle-story', { stockpileDestroyed: true }],
  ]);
  const items = [[33773, 1], [33729, 1]];
  let position = new api.core.Location(2535, 7384, 0);
  const player = {
    getAttribute: key => attributes.get(key), setAttribute: (key, value) => attributes.set(key, value),
    getLocation: () => position, moveTo: location => { position = location; },
    getInventory: () => ({ snapshot: () => items.map(item => [...item]) }),
    getUsername: () => 'blood-hunt-escape-recovery',
    getPacketSender: () => new Proxy({ sendVarbit() {} }, { get: (target, key) => target[key] ?? (() => {}) }),
    sendMessage() {},
  };
  for (const handler of handlers.playerLogin) handler({ player });
  assert.deepEqual([position.getX(), position.getY(), position.getZ()], [2633, 7827, 0]);
  assert.equal(quest.getStage(player), 45, 'the recovery preserves the saved Escape checkpoint');
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-room'), null,
    'the stale Castle room is cleared after the captured transition');
  assert.deepEqual(items, [[33773, 1], [33729, 1]], 'the recovery does not alter carried progress items');
  assert.deepEqual(spawned.map(npc => npc.id).sort((a, b) => a - b), [15855, 15878, 15893, 15909]);
  assert.ok(spawned.every(npc => npc.owner === player && npc.ownerOnly));
});

test('Blood Moon reconciles the Castle lobby floor varbit from the saved lobby plane', () => {
  const { api, handlers } = mockApi();
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const attributes = new Map([
    ['quest.the_blood_moon_rises.stage', 40],
    ['quest.the_blood_moon_rises.castle-room', 1],
    ['quest.the_blood_moon_rises.castle-floor', 2],
    ['quest.the_blood_moon_rises.castle-native-stage', 72],
  ]);
  const varbits = new Map();
  let plane = 0;
  const player = {
    getAttribute: key => attributes.get(key),
    setAttribute: (key, value) => attributes.set(key, value),
    getLocation: () => new api.core.Location(2327, 7361, plane),
    getInventory: () => ({ contains: () => false, snapshot: () => [] }),
    getUsername: () => 'castle-lobby-floor-fixture',
    getPacketSender: () => new Proxy({ sendVarbit: (id, value) => varbits.set(id, value) }, {
      get: (target, key) => target[key] ?? (() => {}),
    }),
  };
  const login = handlers.playerLogin.find(handler => handler.name === 'syncCastleRoomOnLogin');
  login({ player });
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-floor'), 1,
    'the ground-plane lobby resumes with the ground-floor room route');
  assert.equal(varbits.get(15489), 1);

  plane = 1;
  attributes.set('quest.the_blood_moon_rises.castle-floor', 1);
  login({ player });
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-floor'), 2,
    'the upper-plane lobby keeps its first-floor room route');
  assert.equal(varbits.get(15489), 2);

  plane = 0;
  attributes.set('quest.the_blood_moon_rises.castle-floor', 2);
  const moved = [];
  player.moveTo = location => moved.push([location.getX(), location.getY(), location.getZ()]);
  const mapSquareChange = handlers.playerMapSquareChange.find(handler => handler.name === 'syncCastleLobbyFloorOnMapSquareChange');
  mapSquareChange({ player });
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-floor'), 1,
    'the native stair movement is reconciled by the map-square change event');
  assert.equal(varbits.get(15489), 1);

  const galleryDoor = handlers.objects.find(handler => handler.name === 'handleCastleDoorEnter');
  const doorEvent = { player, objectId: 61572, definition: { id: 61572, getName: () => 'Door' },
    location: { x: 2327, y: 7382, z: 0 }, option: 'Enter', handled: false };
  galleryDoor(doorEvent);
  assert.equal(doorEvent.handled, true);
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-room'), 12,
    'the normal ground-gallery door works immediately after the native climb-down');
  assert.deepEqual(moved, [[2331, 7407, 0]]);
});

