test('Blood Moon Paterdomus books must be placed on all six matching plinths before Ivandis leads to the tomb', () => {
  const { api, handlers } = mockApi();
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const { getRegisteredQuests } = require('../plugins/quests/QuestRuntime');
  const quest = getRegisteredQuests().filter((entry) => entry.key === 'the_blood_moon_rises').at(-1);
  const attributes = new Map();
  const counts = new Map();
  const bits = new Map();
  const moveCalls = [];
  const inventory = {
    contains: id => (counts.get(id) ?? 0) > 0,
    getAmount: id => counts.get(id) ?? 0,
    getFreeSlots: () => 28 - [...counts.values()].filter(value => value > 0).length,
    adds: (id, amount) => (counts.set(id, (counts.get(id) ?? 0) + amount), true),
    deleteNumber: (id, amount) => counts.set(id, Math.max(0, (counts.get(id) ?? 0) - amount)),
  };
  const player = {
    getAttribute: key => attributes.get(key),
    setAttribute: (key, value) => attributes.set(key, value),
    getInventory: () => inventory,
    getDialogueManager: () => ({ reset() {}, startDialogues() {} }),
    getPacketSender: () => new Proxy({ sendVarbit: (id, value) => bits.set(id, value) }, { get: (target, key) => target[key] ?? (() => {}) }),
    moveTo: location => moveCalls.push(location),
    sendMessage() {},
  };
  quest.setStage(player, 30);
  attributes.set('quest.the_blood_moon_rises.slepe-story', { manorComplete: true, journalRead: true, monksCleared: true, upstairsTalked: true });
  const syncBooks = handlers.playerLogin.find(handler => handler.name === 'syncPaterdomusBookPuzzle');
  assert.equal(typeof syncBooks, 'function');
  syncBooks({ player });
  handlers.custom.get('player:bootstrap-complete').at(-1)({ player });
  for (const varbit of [15496, 15492, 15491, 15493, 15495, 15494]) {
    assert.equal(bits.get(varbit), 0, 'login and bootstrap restore book transforms without treating the event as the player');
  }
  const ids = api.core.ItemIdentifiers;
  const placements = [
    [ids.ESSIANDARS_NOTES, 3409, 3483], [ids.SARLS_JOURNAL, 3408, 3485],
    [ids.FROM_MISTHALIN_TO_MORYTANIA, 3409, 3487], [ids.SCRUFFY_NOTEBOOK, 3409, 3490],
    [ids.THE_LIFE_OF_FRIAR, 3408, 3492], [ids.PIOUS_PROCEEDINGS, 3409, 3494],
  ];
  const useBook = handlers.itemOnObject.find(handler => handler.name === 'handlePaterdomusItemOnObject');
  for (const [itemId, x, y] of placements) inventory.adds(itemId, 1);
  const wrong = { player, itemId: ids.PIOUS_PROCEEDINGS, location: { x: 3409, y: 3483, z: 1 }, handled: false };
  useBook(wrong);
  assert.equal(attributes.get('quest.the_blood_moon_rises.slepe-story').booksPlaced, undefined,
    'a wrong portrait cannot satisfy the ordered matching puzzle');
  useBook({ player, itemId: ids.ESSIANDARS_NOTES, location: { x: 3409, y: 3483, z: 1 }, handled: false });
  assert.equal(inventory.contains(ids.PIOUS_PROCEEDINGS), true,
    'placing the intended book returns a book that was put on the wrong plinth');
  for (const [itemId, x, y] of placements.slice(1)) useBook({ player, itemId, location: { x, y, z: 1 }, handled: false });
  const story = attributes.get('quest.the_blood_moon_rises.slepe-story');
  assert.equal(story.booksPlaced, true);
  assert.deepEqual(story.bookPlacements, {});
  for (const varbit of [15496, 15492, 15491, 15493, 15495, 15494]) assert.equal(bits.get(varbit), 0);

  const action = handlers.custom.get('npc-dialogue:action').find(handler => handler.name === 'onTranscriptAction');
  const reward = { player, stepId: 'OW0EIY', handled: false };
  action(reward);
  assert.equal(reward.handled, true);
  assert.equal(inventory.contains(ids.IVANDIS_WRITINGS), true);
  handlers.namedItemActions.get("Ivandis' writings").Read({ player, itemId: ids.IVANDIS_WRITINGS, handled: false });
  handlers.custom.get('npc-dialogue:choice').find(handler => handler.name === 'onChoice')({ player, option: 'Lead the way.' });
  const tombStart = attributes.get('quest.the_blood_moon_rises.slepe-story');
  assert.equal(tombStart.tombRouteStarted, true);
  assert.equal(quest.getStage(player), 30, 'the tomb handoff does not skip the owned encounter chapter');
  assert.deepEqual(moveCalls, [], 'arrival waits for the transcript departure cue');
  action({ player, stepId: 'y37Yph' });
  assert.equal(moveCalls.length, 1);
  assert.deepEqual([moveCalls[0].getX(), moveCalls[0].getY(), moveCalls[0].getZ()], [3507, 9860, 0],
    'the departure cue places the party beside the cache-backed blockage in the tomb');
  assert.match('tob:bmr-start', /^[^:\s]+:[^:\s]+$/);
  assert.match('tob:bmr-completed', /^[^:\s]+:[^:\s]+$/);
  handlers.custom.get('bmr:refinery-completed').at(-1)({ player });
  assert.equal(attributes.get('quest.the_blood_moon_rises.slepe-story').refineryComplete, true);
});

test('Blood Moon Hallowed preparations make the stew, upgraded flail and stakes before the siege stage', () => {
  const { api, handlers } = mockApi();
  const originalForId = api.core.NpcDefinition.forId;
  api.core.NpcDefinition.forId = () => ({ getName: () => 'Safalaan Hallow' });
  const messages = [];
  const varbits = new Map();
  let menu;
  api.sendMultiChatboxPrompt = (player, title, ...options) => { menu = options; };
  const choose = option => menu[option*2-1]();
  api.emitCustomEvent = (name, event) => {
    for (const handler of handlers.custom.get(name) ?? []) handler(event);
  };
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const { getRegisteredQuests } = require('../plugins/quests/QuestRuntime');
  const quest = getRegisteredQuests().filter((entry) => entry.key === 'the_blood_moon_rises').at(-1);
  const attributes = new Map();
  const counts = new Map();
  const inventory = {
    getFreeSlots: () => 0,
    contains: (id) => (counts.get(id) ?? 0) > 0,
    getAmount: (id) => counts.get(id) ?? 0,
    adds: (id, amount) => (counts.set(id, (counts.get(id) ?? 0) + amount), true),
    deleteNumber: (id, amount) => counts.set(id, Math.max(0, (counts.get(id) ?? 0) - amount)),
  };
  const player = {
    getAttribute: (key) => attributes.get(key),
    setAttribute: (key, value) => attributes.set(key, value),
    isPlayer: () => true,
    getAsPlayer() { return this; },
    getLocation: () => new api.core.Location(2588, 7854, 0),
    getInventory: () => inventory,
    getEquipment: () => ({ contains: () => false }),
    getSkillManager: () => ({ getMaxLevel: () => 99 }),
    getDialogueManager: () => ({ reset() {}, startDialogues() {} }),
    getPacketSender: () => new Proxy({ sendVarbit: (id, value) => varbits.set(id, value) }, {
      get: (target, key) => target[key] ?? (() => {}),
    }),
    sendMessage: (text) => messages.push(text),
  };
  quest.setStage(player, 60);
  const object = handlers.objects.find((handler) => handler.name === 'handlePrepObject');
  const itemOnItem = handlers.itemOnItem.find((handler) => handler.name === 'handlePrepItemOnItem');
  const itemOnNpc = handlers.itemOnNpc.at(-1);
  const ids = api.core.ItemIdentifiers;
  const use = (a, b) => {
    const event = { player, usedItemId: a, usedWithItemId: b, handled: false };
    itemOnItem(event);
    return event;
  };
  const interact = (name, x = 0, y = 0, z = 1) => object({ player, definition: { getName: () => name }, option: 'Search', location: { x, y, z }, handled: false });

  interact('Amitire plant', 2982, 7679, 0);
  interact('Shelves', 3159, 7824);
  const itemOnObject = handlers.itemOnObject.find(handler => handler.name === 'handlePrepItemOnObject');
  itemOnObject({ player, itemId: ids.BOWL, objectId: 62097, location: { x: 3156, y: 7824, z: 1 } });
  interact('Cupboard', 3155, 7832); choose(3); assert.equal(inventory.contains(ids.POTATO), false, 'Nothing does not award ingredients');
  interact('Cupboard', 3155, 7832); choose(1);
  use(ids.BOWL_OF_WATER, ids.POTATO);
  interact('Cupboard', 3155, 7832); choose(2);
  interact('Range', 3160, 7826);
  use(ids.INCOMPLETE_STEW, ids.COOKED_MEAT);
  interact('Range', 3160, 7826);
  use(ids.STEW, ids.AMITIRE_LEAVES);
  assert.equal(inventory.contains(ids.AMITIRE_STEW), true, 'the ordered ingredients create the quest stew');
  const feeding = { player, target: { getName: () => 'Safalaan Hallow' }, npcId: api.core.NpcIdentifiers.SAFALAAN_HALLOW, itemId: ids.AMITIRE_STEW, handled: false };
  itemOnNpc(feeding);
  assert.equal(feeding.handled, true);
  assert.equal(inventory.contains(ids.HALLOWED_MARKS), true, 'feeding Safalaan grants the hallowed marks');
  assert.equal(varbits.get(15464), 106, 'feeding Safalaan advances to the captured recovery conversation');
  const dialogueLine = handlers.custom.get('npc-dialogue:line').find(handler => handler.name === 'onBloodMoonDialogueLine');
  const safalaanReply = { player, step: { player: true }, text: 'Never.' };
  dialogueLine(safalaanReply); safalaanReply.after();
  assert.equal(varbits.get(15464), 108, 'the captured reply to Safalaan advances to Efaritay’s advice');
  const efaritayAdvice = { player, step: { speaker: 'Efaritay Hallow' },
    text: 'Let me know if you need a hand with anything, but otherwise, I now need to move onto my own preparations.' };
  dialogueLine(efaritayAdvice); efaritayAdvice.after();
  assert.equal(varbits.get(15464), 110, 'finishing Efaritay’s preparations conversation unlocks the armoury work');

  interact('Workbench', 3176, 7841); choose(3); assert.equal(inventory.contains(ids.KNIFE), true); assert.equal(inventory.contains(ids.HAMMER), false);
  interact('Workbench', 3176, 7841); choose(1); interact('Workbench', 3176, 7841); choose(2);
  interact('Crate', 3177, 7843);
  interact('Crate', 3181, 7841);
  interact('Chest', 3181, 7835);
  use(ids.SILVER_SICKLE_B_, ids.DIAMOND); choose(2); assert.equal(inventory.contains(ids.DIAMOND), true, 'No preserves crafting materials');
  use(ids.SILVER_SICKLE_B_, ids.DIAMOND); choose(1);
  interact('Chest', 3175, 7836);
  use(ids.DIAMOND_SICKLE_B_, ids.ENCHANT_DIAMOND);
  use(ids.ENCHANTED_DIAMOND_SICKLE_B_, ids.BLISTERWOOD_LOGS); choose(1);
  inventory.adds(ids.BLISTERWOOD_FLAIL, 1);
  interact('Anvil', 3179, 7842); choose(2); assert.equal(inventory.contains(ids.BLISTERWOOD_FLAIL), true);
  interact('Anvil', 3179, 7842); choose(1);
  assert.equal(inventory.contains(ids.HALLOWED_FLAIL), true, 'the anvil consumes the sickle/marks/flail and makes a hallowed flail');
  interact('Crate', 3177, 7843);
  use(ids.BLISTERWOOD_LOGS, ids.KNIFE);
  attributes.set('quest.the_blood_moon_rises.preparations', {
    introComplete: true,
    flail: true,
    stakes: true,
  });
  quest.setStage(player, 60);
  assert.equal(varbits.get(15464), 114,
    'finishing the intro does not mask the captured flail-and-stakes preparation stage');
  const action = handlers.custom.get('npc-dialogue:action').at(-1);
  action({ player, stepId: 'Sut83Q' });
  assert.equal(quest.getStage(player), 60, 'the siege handoff waits for the recorded ally conversations');
  attributes.set('quest.the_blood_moon_rises.preparations', {
    introComplete: true, stewFed: true, safalaanAnswered: true, preparationsDiscussed: true,
    flail: true, stakes: true, stakesConversationComplete: true, veliafFirstTalkComplete: true,
    vanesculaTalkComplete: true, veliafFollowupComplete: true, sugadintiReady: true,
  });
  action({ player, stepId: 'Sut83Q' });
  assert.equal(quest.getStage(player), 70, 'the siege starts after the actual recipes and ordered preparation talks');
  assert.ok(messages.length > 0, 'interactions give feedback while ingredients and equipment are prepared');

  quest.setStage(player, 90);
  inventory.adds(ids.BLISTERWOOD_LOGS, 1);
  inventory.adds(ids.KNIFE, 1);
  const stakeCountBeforeRestock = inventory.getAmount(ids.BLISTERWOOD_STAKE);
  const replacementStakes = use(ids.BLISTERWOOD_LOGS, ids.KNIFE);
  assert.equal(replacementStakes.handled, true, 'a completed stakes recipe can be repeated at a later active quest stage');
  assert.equal(inventory.getAmount(ids.BLISTERWOOD_STAKE), stakeCountBeforeRestock + 5);
  assert.equal(quest.getStage(player), 90, 'restocking stakes does not rewind the Wyrd chapter');
  inventory.adds(ids.BOWL_OF_WATER, 1);
  inventory.adds(ids.POTATO, 1);
  const unrelatedLateRecipe = use(ids.BOWL_OF_WATER, ids.POTATO);
  assert.equal(unrelatedLateRecipe.handled, false, 'other preparation recipes remain locked after preparations');
  assert.equal(inventory.contains(ids.BOWL_OF_WATER), true, 'the stage guard preserves unrelated ingredients');
  attributes.set('quest.the_blood_moon_rises.preparations', {
    ...(attributes.get('quest.the_blood_moon_rises.preparations') ?? {}), stakes: false,
  });
  inventory.adds(ids.BLISTERWOOD_LOGS, 1);
  inventory.adds(ids.KNIFE, 1);
  const unearnedRestock = use(ids.BLISTERWOOD_LOGS, ids.KNIFE);
  assert.equal(unearnedRestock.handled, false, 'the late recipe requires the earned stakes preparation flag');
  assert.equal(inventory.contains(ids.BLISTERWOOD_LOGS), true, 'rejected late recipes preserve ingredients');
  api.core.NpcDefinition.forId = originalForId;
});

test('Blood Moon preparation opens Efaritay’s existing supplies dialogue if the player lacks a Blisterwood flail', () => {
  const { api, handlers } = mockApi();
  const npcDialogues = require('../plugins/npcs/NpcDialogues.plugin');
  const originalStartDialogue = npcDialogues.startDialogue;
  let started;
  npcDialogues.startDialogue = (_api, _event, steps, _branches, context) => {
    started = { steps, page: context.pages[0].page, variant: context.pages[0].variants[0] };
  };
  try {
    require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
    const attributes = new Map();
    const inventoryIds = new Set();
    const player = {
      getAttribute: key => attributes.get(key),
      setAttribute: (key, value) => attributes.set(key, value),
      isPlayer: () => true,
      getAsPlayer() { return this; },
      getInventory: () => ({ contains: id => inventoryIds.has(id) }),
      getEquipment: () => ({ contains: () => false }),
      getPacketSender: () => ({ sendVarbit() {}, sendQuestList() {} }),
      sendMessage() {},
    };
    attributes.set('quest.the_blood_moon_rises.stage', 60);
    attributes.set('quest.the_blood_moon_rises.preparations', {
      introComplete: true, gatherStarted: true, preparationsDiscussed: true,
    });
    const talkToEfaritay = handlers.npcInteractions.get('Efaritay Hallow')['Talk-to'];
    assert.equal(talkToEfaritay({
      player,
      npcId: api.core.NpcIdentifiers.EFARITAY_HALLOW,
      definition: { getName: () => 'Efaritay Hallow' },
      handled: false,
    }), true);
    assert.equal(started.page, 'Efaritay Hallow');
    assert.equal(started.variant, 'standard-dialogue');
    const purchase = started.steps.find(step => step.type === 'choice')?.options
      .find(option => option.text === 'I could use a new weapon.');
    assert.ok(purchase?.steps.some(step => step.type === 'action' && step.action === 'open_shop' &&
      step.target === "Efaritay's Supplies"), 'the existing dialogue opens the cache-defined shop');
    assert.equal(require('../data/definitions/shops.json').find(shop => shop.name === "Efaritay's Supplies")
      .originalStock.some(item => item.id === api.core.ItemIdentifiers.BLISTERWOOD_FLAIL), true);
  } finally {
    npcDialogues.startDialogue = originalStartDialogue;
  }
});

test('Blood Moon Ivan and Sarei preparation dialogue advances to the stake follow-up', () => {
  const { api, handlers } = mockApi();
  const npcDialogues = require('../plugins/npcs/NpcDialogues.plugin');
  const originalStartDialogue = npcDialogues.startDialogue;
  let started;
  npcDialogues.startDialogue = (_api, _event, _steps, _branches, context) => {
    started = { page: context.pages[0].page, variant: context.pages[0].variants[0] };
  };
  try {
    require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
    const attributes = new Map([
      ['quest.the_blood_moon_rises.stage', 60],
      ['quest.the_blood_moon_rises.preparations', { introComplete: true, stakes: true }],
    ]);
    const inventoryIds = new Set([api.core.ItemIdentifiers.BLISTERWOOD_STAKE]);
    const player = {
      getAttribute: key => attributes.get(key),
      setAttribute: (key, value) => attributes.set(key, value),
      isPlayer: () => true,
      getAsPlayer() { return this; },
      getInventory: () => ({ contains: id => inventoryIds.has(id) }),
      getEquipment: () => ({ contains: () => false }),
      getPacketSender: () => ({ sendVarbit() {}, sendQuestList() {} }),
      sendMessage() {},
    };
    const talk = handlers.npcInteractions.get('Ivan Strom')['Talk-to'];
    const event = () => ({ player, npcId: api.core.NpcIdentifiers.IVAN_STROM_13,
      definition: { getName: () => 'Ivan Strom' }, handled: false });
    assert.equal(talk(event()), true);
    assert.equal(started.variant, 'hallowed-preparations-talking-to-ivan-and-sarei');

    const line = handlers.custom.get('npc-dialogue:line').find(handler => handler.name === 'onBloodMoonDialogueLine');
    const doneIntro = { player, step: { player: "I'll get to it." }, text: "I'll get to it." };
    line(doneIntro);
    doneIntro.after();
    assert.equal(attributes.get('quest.the_blood_moon_rises.preparations').ivanSareiIntroComplete, true);
    assert.equal(talk(event()), true);
    assert.equal(started.variant, 'hallowed-preparations-talking-to-ivan-and-sarei-talking-to-them-again');

    const talkToSarei = handlers.npcInteractions.get('Sarei')['Talk-to'];
    assert.equal(talkToSarei({
      player,
      npcId: api.core.NpcIdentifiers.SAREI,
      definition: { getName: () => 'Sarei' },
      handled: false,
    }), true);
    assert.equal(started.variant, 'hallowed-preparations-talking-to-ivan-and-sarei-talking-to-them-again',
      'Sarei uses the same earned follow-up instead of replaying the introduction');
    const finishedStakesTalk = { player, step: { player: true },
      text: "I hope so too. We're going to need all the  advantages we can find." };
    line(finishedStakesTalk);
    finishedStakesTalk.after();
    assert.equal(attributes.get('quest.the_blood_moon_rises.preparations').stakesConversationComplete, true,
      'the actual client text spacing still records the completed follow-up');

    const condition = handlers.condition.find(handler => handler.name === 'answerPreparationStakesCondition');
    assert.equal(condition({ player, stepId: 'sqIM75' }), false, 'the unmade-stakes branch is skipped when stakes are carried');
    assert.equal(condition({ player, stepId: 'cv4yCk' }), true, 'the made-stakes branch is selected');
    inventoryIds.delete(api.core.ItemIdentifiers.BLISTERWOOD_STAKE);
    assert.equal(condition({ player, stepId: 'sqIM75' }), true, 'the player must keep the stakes to claim completion');
    assert.equal(condition({ player, stepId: 'cv4yCk' }), false);
  } finally {
    npcDialogues.startDialogue = originalStartDialogue;
  }
});

test('Blood Moon preparation dialogue follows Veliaf, Vanescula, Veliaf, then Sugadinti', () => {
  const { api, handlers } = mockApi();
  const npcDialogues = require('../plugins/npcs/NpcDialogues.plugin');
  const originalStartDialogue = npcDialogues.startDialogue;
  let started;
  npcDialogues.startDialogue = (_api, _event, _steps, _branches, context) => {
    started = context.pages[0].variants[0];
  };
  try {
    require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
    const prepKey = 'quest.the_blood_moon_rises.preparations';
    const attributes = new Map([
      ['quest.the_blood_moon_rises.stage', 60],
      [prepKey, { introComplete: true, stewFed: true, safalaanAnswered: true, preparationsDiscussed: true,
        flail: true, stakes: true }],
    ]);
    const messages = [];
    const player = {
      getAttribute: key => attributes.get(key),
      setAttribute: (key, value) => attributes.set(key, value),
      isPlayer: () => true,
      getAsPlayer() { return this; },
      getInventory: () => ({ contains: id => [api.core.ItemIdentifiers.HALLOWED_FLAIL,
        api.core.ItemIdentifiers.BLISTERWOOD_STAKE].includes(id) }),
      getEquipment: () => ({ contains: () => false }),
      getPacketSender: () => ({ sendVarbit() {}, sendQuestList() {} }),
      sendMessage: text => messages.push(text),
    };
    const talk = name => handlers.npcInteractions.get(name)['Talk-to']({ player, npcId: 15871,
      definition: { getName: () => name }, handled: false });
    const line = handlers.custom.get('npc-dialogue:line').find(handler => handler.name === 'onBloodMoonDialogueLine');
    const finishLine = (speaker, text) => { const request = { player, step: { speaker }, text }; line(request); request.after?.(); };

    assert.equal(talk('Veliaf Hurtz'), true);
    assert.equal(started, undefined, 'Veliaf waits until Ivan and Sarei acknowledge the made stakes');
    attributes.set(prepKey, { ...attributes.get(prepKey), stakesConversationComplete: true });
    assert.equal(talk('Vanescula Drakan'), true);
    assert.equal(started, undefined, 'the player must hear Veliaf before questioning Vanescula');
    assert.equal(talk('Veliaf Hurtz'), true);
    assert.equal(started, 'hallowed-preparations-talking-to-veliaf');
    finishLine('Veliaf Hurtz', 'Well, if you want to try getting something out of her, be my guest.');
    assert.equal(attributes.get(prepKey).veliafFirstTalkComplete, true);
    assert.equal(talk('Vanescula Drakan'), true);
    assert.equal(started, 'hallowed-preparations-talking-to-vanescula');
    finishLine('Vanescula Drakan', 'Now, as fun as all this has been, my brother will almost certainly be upon you and your new friends soon.');
    assert.equal(attributes.get(prepKey).vanesculaTalkComplete, true);
    assert.equal(talk('Veliaf Hurtz'), true);
    assert.equal(started, 'hallowed-preparations-talking-to-veliaf-after-talking-to-vanescula');
    finishLine('Veliaf Hurtz', "Best you go and get ready, [player name]. Won't be long until Drakan is here.");
    assert.equal(attributes.get(prepKey).veliafFollowupComplete, true);
    assert.equal(talk('Sugadinti Vitur'), true);
    assert.equal(started, 'hallowed-preparations-talking-to-sugadinti-after-finishing-preparations');
    finishLine('Sugadinti Vitur', 'I will see that it is. Now, my disciples are gathering on the bridge outside.');
    assert.equal(attributes.get(prepKey).sugadintiReady, true);
    assert.deepEqual(messages, [
      'Finish the Hallowed flail and blisterwood stakes, then speak with Ivan and Sarei about them.',
      'I should speak to Veliaf before questioning Vanescula.',
    ]);
  } finally {
    npcDialogues.startDialogue = originalStartDialogue;
  }
});

test('Blood Moon Castle Drakan throne opens only after the ordered bust mechanism and awards its key', () => {
  const { api, handlers } = mockApi();
  const messages = [];
  const varbits = new Map();
  const spawned = [];
  let position = new api.core.Location(2535, 7384, 0);
  api.spawnNpc = spec => { const npc = { ...spec, setScriptedMovement() {}, isDestroyed: () => false }; spawned.push(npc); return npc; };
  api.emitCustomEvent = (name, event) => {
    for (const handler of handlers.custom.get(name) ?? []) handler(event);
  };
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const { getRegisteredQuests } = require('../plugins/quests/QuestRuntime');
  const quest = getRegisteredQuests().filter((entry) => entry.key === 'the_blood_moon_rises').at(-1);
  const attributes = new Map();
  const counts = new Map();
  let freeSlots = 0;
  const inventory = {
    contains: (id) => (counts.get(id) ?? 0) > 0,
    getFreeSlots: () => freeSlots,
    adds: (id, amount) => (counts.set(id, (counts.get(id) ?? 0) + amount), true),
    deleteNumber: (id, amount) => counts.set(id, Math.max(0, (counts.get(id) ?? 0) - amount)),
  };
  const player = {
    getAttribute: (key) => attributes.get(key),
    setAttribute: (key, value) => attributes.set(key, value),
    getInventory: () => inventory,
    getSkillManager: () => ({ getMaxLevel: () => 99 }),
    getLocation: () => position,
    moveTo: location => { position = location; },
    getDialogueManager: () => ({ reset() {}, startDialogues() {} }),
    getPacketSender: () => new Proxy({ sendVarbit: (id, value) => varbits.set(id, value) }, {
      get: (target, key) => target[key] ?? (() => {}),
    }),
    sendMessage: (text) => messages.push(text),
  };
  attributes.set('quest.the_blood_moon_rises.castle-native-stage', 78);
  quest.setStage(player, 40);
  assert.equal(varbits.get(15464), 78, 'the captured stockpile approach begins at native value 78');
  const interact = (name, x, y, option) => {
    const event = { player, definition: { getName: () => name }, location: { x, y, z: 0 }, option, handled: false };
    for (const handler of handlers.objects) {
      handler(event);
      if (event.handled) break;
    }
    return event;
  };
  const action = handlers.custom.get('npc-dialogue:action').at(-1);
  action({ player, stepId: 'XqVfhB' });
  assert.equal(quest.getStage(player), 40, 'the escape transcript cannot bypass the throne puzzle');
  interact('Throne', 2313, 7391, 'Search');
  assert.deepEqual([15539, 15540, 15541, 15542].map((id) => varbits.get(id)), [1, 1, 1, 1],
    'searching the throne transforms the four cache busts into clickable levers');
  interact('Bust with lever', 2317, 7393, 'Pull');
  assert.ok(messages.some((message) => message.includes('reset')), 'the wrong first lever resets the mechanism');
  assert.equal(varbits.get(15539), 2, 'pulling a bust changes its cache-backed lever position');
  for (const y of [7391, 7390, 7393, 7392]) interact('Bust with lever', 2317, y, 'Pull');
  interact('Throne', 2313, 7392, 'Search');
  assert.equal(inventory.contains(api.core.ItemIdentifiers.HALF_MOON_KEY), false,
    'a full inventory leaves the key available to claim later');
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-throne-puzzle').keyClaimed, false);
  freeSlots = 1;
  interact('Throne', 2313, 7392, 'Search');
  assert.equal(inventory.contains(api.core.ItemIdentifiers.HALF_MOON_KEY), true);
  counts.set(api.core.ItemIdentifiers.HALF_MOON_KEY, 0);
  interact('Throne', 2313, 7392, 'Search');
  assert.equal(inventory.contains(api.core.ItemIdentifiers.HALF_MOON_KEY), true,
    'a solved throne lets the player reclaim a half-moon key that is no longer carried');
  assert.deepEqual([15539, 15540, 15541, 15542].map((id) => varbits.get(id)), [1, 2, 2, 2],
    'the active lever positions survive the completed puzzle');
  action({ player, stepId: 'XqVfhB' });
  assert.equal(quest.getStage(player), 40, 'the escape chapter waits until the blood stockpile is destroyed');
  attributes.set('quest.the_blood_moon_rises.castle-refiner', { destroyed: true });
  action({ player, stepId: 'LTAe0k' });
  assert.equal(varbits.get(15464), 80, 'destroying the stockpile advances to captured native value 80, not the Slepe refinery value 62');
  assert.equal(quest.getStage(player), 40, 'destroying the stockpile stays in the Castle chapter until the escape action');
  action({ player, stepId: 'XqVfhB' });
  assert.equal(quest.getStage(player), 45, 'the recorded escape action starts the Escape chapter');
  assert.equal(varbits.get(15464), 82, 'the Escape chapter matches the captured native stage');
  assert.deepEqual([position.getX(), position.getY(), position.getZ()], [2576, 7838, 0],
    'the recorded cutscene action enters Sangvesti before its final dialogue lines');
  const farewell = { player, step: { player: true }, text: "Then I'll just have to avoid him." };
  handlers.custom.get('npc-dialogue:line').find(handler => handler.name === 'onBloodMoonDialogueLine')(farewell);
  farewell.after();
  assert.equal(quest.getStage(player), 45, 'the final line remains in the Escape quest stage');
  assert.equal(varbits.get(15464), 84, 'the final line advances the captured native stage from 82 to 84');
  assert.deepEqual([position.getX(), position.getY(), position.getZ()], [2633, 7827, 0],
    'the player arrives beside the captured Sangvesti party');
  assert.deepEqual(spawned.map(npc => npc.id).sort((a, b) => a - b), [15855, 15878, 15893, 15909],
    'the four talkable Sangvesti companions spawn at their captured anchors');
  assert.ok(spawned.every(npc => npc.owner === player && npc.ownerOnly), 'the quest party belongs only to this player');
  const talkVanescula = handlers.npcInteractions.get('Vanescula Drakan')['Talk-to'];
  assert.equal(talkVanescula({ player, npcId: api.core.NpcIdentifiers.VANESCULA_DRAKAN_10,
    definition: { getName: () => 'Vanescula Drakan' }, handled: false }), true,
    'the stage-based chapter hook resolves Vanescula Drakan to the recorded vanescula variant');
  const variant = handlers.variant.map(handler => handler({ player,
    definition: { getName: () => 'Vanescula Drakan' },
    pages: [{ page: 'The Blood Moon Rises', variants: ['blood-hunt-talking-to-vanescula-in-the-town'] }],
  })).find(Boolean);
  assert.deepEqual(variant, { page: 'The Blood Moon Rises', variant: 'blood-hunt-talking-to-vanescula-in-the-town' },
    'the dialogue resolver selects the Blood Hunt cog-check instead of the generic post-quest conversation');
  handlers.custom.get('npc-dialogue:choice').find(handler => handler.name === 'onChoice')({ player, option: "I'll get back to it." });
  assert.equal(quest.getStage(player), 45, 'the cog conversation does not skip later Blood Hunt objectives');
  assert.equal(varbits.get(15464), 84, 'Blood Hunt retains the recorded native stage 84');
});

test('Blood Moon Castle gilded bookcase uses the eight House slots and places the full moon key in the secret room', () => {
  const { api, handlers } = mockApi();
  const ground = [];
  let prompt;
  let openedInterface = 0;
  let removedInterface = false;
  const slots = new Map();
  api.getItemOnGroundManager = () => ({
    getGroundItem: () => null,
    registerLocation: (_player, item, location) => ground.push({ item, location }),
  });
  api.sendMultiChatboxPrompt = (_player, title, ...options) => { prompt = { title, options }; };
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const quest = require('../plugins/quests/QuestRuntime').getRegisteredQuests()
    .filter(entry => entry.key === 'the_blood_moon_rises').at(-1);
  const attributes = new Map();
  const items = new Map();
  const inventory = {
    contains: id => (items.get(id) ?? 0) > 0,
    getFreeSlots: () => 28 - [...items.values()].reduce((sum, count) => sum + count, 0),
    adds: (id, amount) => { items.set(id, (items.get(id) ?? 0) + amount); return true; },
    deleteNumber: (id, amount) => { const count = items.get(id) ?? 0; if (count < amount) return false; items.set(id, count - amount); return true; },
  };
  const player = {
    getAttribute: key => attributes.get(key), setAttribute: (key, value) => attributes.set(key, value),
    getInventory: () => inventory, getUsername: () => 'bookpuzzle', sendMessage() {},
    getPrivateArea: () => null,
    getPacketSender: () => new Proxy({
      sendVarbit: (id, value) => slots.set(id, value),
      sendInterface: id => { openedInterface = id; },
      sendInterfaceRemoval: () => { removedInterface = true; },
    }, { get: (target, key) => target[key] ?? (() => {}) }),
  };
  quest.setStage(player, 40);
  attributes.set('quest.the_blood_moon_rises.castle-native-stage', 78);
  attributes.set('quest.the_blood_moon_rises.castle-story', { talkedToIvan: true,
    defeated: ['library-venator'], bookPuzzleComplete: false, fullMoonKeyClaimed: false });
  const northShelf = handlers.objects.find(handler => handler.name === 'handleCastleBookObjects');
  assert.ok(northShelf, 'the Castle bookcase search handler is registered');
  northShelf({ player, objectId: 61756, definition: { id: 61756, getName: () => 'Bookcase' },
    location: { x: 2455, y: 7395, z: 0 }, option: 'Search', handled: false });
  assert.equal(items.get(33767), 1, 'the north shelf yields the gilded book');
  northShelf({ player, objectId: 61757, definition: { id: 61757, getName: () => 'Bookcase' },
    location: { x: 2458, y: 7388, z: 0 }, option: 'Search', handled: false });
  assert.equal(items.get(33768), 1, 'a searched shelf in the library yields the Vampyric Houses book');
  const useBook = handlers.itemOnObject.find(handler => handler.name === 'handleCastleBookOnObject');
  assert.ok(useBook);
  useBook({ player, itemId: 33767, objectId: 61692, definition: { id: 61692 },
    location: { x: 2451, y: 7391, z: 0 }, handled: false });
  assert.equal(items.get(33767), 0, 'placing the gilded book consumes that copy');
  assert.equal(slots.get(15525), 1, 'the native loc morph shows the case with its books inserted');
  assert.match(prompt.title, /alphabetically/);
  prompt.options[1]();
  assert.equal(openedInterface, 962, 'the actual Castle bookcase widget opens after the player confirms');
  const blockedPassage = { player, objectId: 61615, definition: { id: 61615 },
    location: { x: 2455, y: 7386, z: 0 }, option: 'Enter', handled: false };
  northShelf(blockedPassage);
  assert.equal(blockedPassage.handled, true, 'the closed passage consumes the premature Enter action');
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-story').bookPuzzleComplete, false,
    'the passage stays shut until the eight books are ordered');
  handlers.playerLogin.find(handler => handler.name === 'syncCastleRoomOnLogin')({ player });
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-book-puzzle').open, false,
    'relogin closes the widget without losing its book order');
  northShelf({ player, objectId: 61692, definition: { id: 61692, getName: () => 'Gilded bookcase' },
    location: { x: 2451, y: 7391, z: 0 }, option: 'Search', handled: false });
  prompt.options[1]();
  const widget = handlers.custom.get('player:widget-action').find(handler => handler.name === 'handleCastleBookWidgetAction');
  assert.ok(widget);
  const varbits = [15550, 15551, 15552, 15553, 15554, 15555, 15556, 15557];
  for (let index = 0; index < 8; index++) {
    if (slots.get(varbits[index]) === index + 1) continue;
    const other = varbits.findIndex(id => slots.get(id) === index + 1);
    for (const slot of [index, other]) widget({ player, packet: { type: 'widget_action', groupId: 962, slot }, handled: false });
  }
  assert.deepEqual(varbits.map(id => slots.get(id)), [1, 2, 3, 4, 5, 6, 7, 8]);
  assert.equal(slots.get(15525), 2, 'the cache varbit reveals the solved bookcase and passage');
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-story').bookPuzzleComplete, true);
  assert.equal(removedInterface, true, 'solving closes the widget');
  assert.equal(ground.length, 2, 'solving the library puzzle exposes the recorded key and jerky supplies');
  assert.equal(ground[0].item.getId(), 33724);
  assert.deepEqual([ground[0].location.getX(), ground[0].location.getY(), ground[0].location.getZ()], [2433, 7416, 0]);
  assert.equal(ground[1].item.getId(), 33802);
  assert.deepEqual([ground[1].location.getX(), ground[1].location.getY(), ground[1].location.getZ()], [2433, 7415, 0]);
  handlers.ground.find(handler => handler.name === 'handleCastleBookPickup')({ player, groundItemId: 33724,
    location: { x: 2433, y: 7416, z: 0 } });
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-story').fullMoonKeyClaimed, true);
  handlers.ground.find(handler => handler.name === 'handleCastleBookPickup')({ player, groundItemId: 33802,
    location: { x: 2433, y: 7415, z: 0 } });
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-story').mysteryJerkyClaimed, true);
  ground.length = 0;
  handlers.playerLogin.find(handler => handler.name === 'syncCastleRoomOnLogin')({ player });
  assert.ok(ground.some(entry => entry.item.getId() === 33724),
    'a lost full-moon key can be reclaimed from the solved library when it is not in inventory or bank');
});

test('Blood Moon Castle hidden room supplies the chunky potion through Search and combines real doses', () => {
  const { api, handlers } = mockApi();
  let prompt;
  const items = new Map();
  const inventory = {
    contains: id => (items.get(id) ?? 0) > 0,
    getAmount: id => items.get(id) ?? 0,
    getFreeSlots: () => 28 - [...items.values()].reduce((sum, count) => sum + count, 0),
    adds: (id, amount) => { items.set(id, (items.get(id) ?? 0) + amount); return true; },
    deleteNumber: (id, amount) => { const count = items.get(id) ?? 0; if (count < amount) return false; items.set(id, count - amount); return true; },
  };
  api.sendMultiChatboxPrompt = (_player, title, ...options) => { prompt = { title, options }; };
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const attributes = new Map();
  const player = {
    getAttribute: key => attributes.get(key), setAttribute: (key, value) => attributes.set(key, value),
    getInventory: () => inventory, sendMessage() {}, getPacketSender: () => new Proxy({}, {
      get: (_target, _key) => () => {},
    }),
  };
  const quest = require('../plugins/quests/QuestRuntime').getRegisteredQuests()
    .filter(entry => entry.key === 'the_blood_moon_rises').at(-1);
  quest.setStage(player, 40);
  attributes.set('quest.the_blood_moon_rises.castle-native-stage', 78);
  attributes.set('quest.the_blood_moon_rises.castle-room', 32);
  attributes.set('quest.the_blood_moon_rises.castle-floor', 2);
  attributes.set('quest.the_blood_moon_rises.castle-story', { bookPuzzleComplete: true, talkedToIvan: true,
    defeated: ['library-venator'] });
  const shelves = handlers.objects.find(handler => handler.name === 'handleCastleSecretRoomObjects');
  const search = { player, objectId: 61752, definition: { id: 61752 },
    location: { x: 2433, y: 7411, z: 0 }, option: 'Search', handled: false };
  shelves(search);
  assert.equal(search.handled, true);
  assert.match(prompt.title, /foul chunky potion/);
  prompt.options[3]();
  assert.equal(items.get(33810), 1, 'taking the searched shelf item yields one real potion dose');
  items.set(33810, 2);
  const combine = handlers.itemOnItem.find(handler => handler.name === 'handleCastleChunkyPotionCombine');
  const event = { player, usedItemId: 33810, usedWithItemId: 33810, usedItemSlot: 3, usedWithItemSlot: 4, handled: false };
  combine(event);
  assert.equal(event.handled, true);
  assert.equal(items.get(33810), 0);
  assert.equal(items.get(33809), 1, 'two one-dose potions combine into the cache two-dose potion');
  attributes.set('quest.the_blood_moon_rises.castle-room', 34);
  const northCrate = handlers.objects.find(handler => handler.name === 'handleCastleKeyObjects');
  const crate = { player, objectId: 61751, definition: { id: 61751 }, location: { x: 2461, y: 7421, z: 0 },
    option: 'search', handled: false };
  northCrate(crate);
  assert.equal(crate.handled, true);
  assert.match(prompt.title, /mysterious jerky/);
  prompt.options[3]();
  assert.equal(items.get(33802), 1, 'the North Lobby Hall crate offers its captured jerky supply');
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-story').northLobbyJerkyClaimed, true);
});

test('Blood Moon Bedroom offers the recorded chunky potions and jerky and combines the real doses', () => {
  const { api, handlers } = mockApi();
  let prompt;
  const items = new Map();
  const inventory = {
    contains: id => (items.get(id) ?? 0) > 0,
    getAmount: id => items.get(id) ?? 0,
    getFreeSlots: () => 28 - [...items.values()].reduce((sum, count) => sum + count, 0),
    adds: (id, amount) => { items.set(id, (items.get(id) ?? 0) + amount); return true; },
    deleteNumber: (id, amount) => {
      const count = items.get(id) ?? 0;
      if (count < amount) return false;
      items.set(id, count - amount);
      return true;
    },
  };
  api.sendMultiChatboxPrompt = (_player, title, ...options) => { prompt = { title, options }; };
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const attributes = new Map([
    ['quest.the_blood_moon_rises.castle-native-stage', 78],
    ['quest.the_blood_moon_rises.castle-room', 20],
    ['quest.the_blood_moon_rises.castle-floor', 2],
    ['quest.the_blood_moon_rises.castle-story', {}],
  ]);
  const player = {
    getAttribute: key => attributes.get(key), setAttribute: (key, value) => attributes.set(key, value),
    getInventory: () => inventory, sendMessage() {}, getPacketSender: () => new Proxy({}, { get: () => () => {} }),
  };
  const quest = require('../plugins/quests/QuestRuntime').getRegisteredQuests()
    .filter(entry => entry.key === 'the_blood_moon_rises').at(-1);
  quest.setStage(player, 40);
  const objects = handlers.objects.find(handler => handler.name === 'handleCastleKeyObjects');
  for (let count = 1; count <= 2; count++) {
    const crate = { player, objectId: 61751, definition: { id: 61751 },
      location: { x: 2450, y: 7362, z: 0 }, option: 'Search', handled: false };
    objects(crate);
    assert.equal(crate.handled, true);
    assert.match(prompt.title, /foul chunky potions/);
    prompt.options[3]();
    assert.equal(items.get(33810), count, 'each captured crate choice supplies one one-dose potion');
  }
  const emptyCrate = { player, objectId: 61751, definition: { id: 61751 },
    location: { x: 2450, y: 7362, z: 0 }, option: 'Search', handled: false };
  prompt = null;
  objects(emptyCrate);
  assert.equal(emptyCrate.handled, true);
  assert.equal(prompt, null, 'the crate cannot duplicate its two recorded servings');
  const shelves = { player, objectId: 61752, definition: { id: 61752 },
    location: { x: 2449, y: 7363, z: 0 }, option: 'Search', handled: false };
  objects(shelves);
  assert.equal(shelves.handled, true);
  assert.match(prompt.title, /mysterious jerky/);
  prompt.options[3]();
  assert.equal(items.get(33802), 1, 'the captured bedroom shelf yields one jerky');
  const combine = handlers.itemOnItem.find(handler => handler.name === 'handleCastleChunkyPotionCombine');
  const event = { player, usedItemId: 33810, usedWithItemId: 33810,
    usedItemSlot: 1, usedWithItemSlot: 2, handled: false };
  combine(event);
  assert.equal(event.handled, true);
  assert.equal(items.get(33810), 0);
  assert.equal(items.get(33809), 1, 'the Bedroom supports the same canonical two-dose combination');
});

test('Blood Moon Castle new-moon key requires the corpse syringe, weapon statues, and crest fireplace', () => {
  const { api, handlers } = mockApi();
  const ground = [];
  let prompt;
  const varbits = new Map();
  api.getItemOnGroundManager = () => ({
    getGroundItem: () => null,
    registerLocation: (_player, item, location) => ground.push({ item, location }),
  });
  api.sendMultiChatboxPrompt = (_player, title, ...options) => { prompt = { title, options }; };
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const quest = require('../plugins/quests/QuestRuntime').getRegisteredQuests()
    .filter(entry => entry.key === 'the_blood_moon_rises').at(-1);
  const attrs = new Map();
  const items = new Map();
  const inventory = {
    contains: id => (items.get(id) ?? 0) > 0,
    getFreeSlots: () => 28 - [...items.values()].reduce((sum, count) => sum + count, 0),
    adds: (id, amount) => { items.set(id, (items.get(id) ?? 0) + amount); return true; },
    deleteNumber: (id, amount) => { const count = items.get(id) ?? 0; if (count < amount) return false; items.set(id, count - amount); return true; },
  };
  const player = {
    getAttribute: key => attrs.get(key), setAttribute: (key, value) => attrs.set(key, value),
    getInventory: () => inventory, getUsername: () => 'newmoon', getPrivateArea: () => null,
    sendMessage() {}, getPacketSender: () => new Proxy({ sendVarbit: (id, value) => varbits.set(id, value) },
      { get: (target, key) => target[key] ?? (() => {}) }),
  };
  quest.setStage(player, 40);
  attrs.set('quest.the_blood_moon_rises.castle-native-stage', 74);
  attrs.set('quest.the_blood_moon_rises.castle-story', { defeated: ['kitchen-sanguidae-west',
    'kitchen-sanguidae-north', 'kitchen-sanguidae-south', 'kitchen-sanguidae', 'first-venator'] });
  const objects = handlers.objects.find(handler => handler.name === 'handleCastleKeyObjects');
  const onObject = handlers.itemOnObject.find(handler => handler.name === 'handleCastleKeyItemOnObject');
  const onItem = handlers.itemOnItem.find(handler => handler.name === 'handleCastleKeyItemOnItem');
  const pickup = handlers.ground.find(handler => handler.name === 'handleCastleKeyPickup');
  const login = handlers.playerLogin.find(handler => handler.name === 'syncCastleRoomOnLogin');
  assert.ok(objects && onObject && onItem && pickup && login);
  const click = (id, x, y, option = 'Search') => {
    const event = { player, objectId: id, definition: { id, getName: () => 'Searchable crate' },
      location: { x, y, z: 0 }, option: option.toLowerCase(), handled: false };
    objects(event);
    assert.equal(event.handled, true, `Castle key object ${id} at ${x},${y} was handled`);
    return event;
  };
  const confirm = () => {
    assert.equal(prompt.options[0], 'Yes.');
    prompt.options[1]();
  };
  const choosePrompt = option => {
    const index = prompt.options.findIndex((value, i) => i % 2 === 0 && value === option);
    assert.ok(index >= 0, `the prompt offers ${option}`);
    prompt.options[index + 1]();
  };
  const useOn = (itemId, id, x, y) => {
    const event = { player, itemId, objectId: id, definition: { id }, location: { x, y, z: 0 }, handled: false };
    onObject(event);
    assert.equal(event.handled, true, `item ${itemId} on Castle object ${id} was handled`);
  };
  const useTogether = (usedItemId, usedWithItemId) => onItem({ player, usedItemId, usedWithItemId, handled: false });
  login({ player });
  assert.equal(ground[0].item.getId(), 33752, 'the defeated kitchen sanguidae leaves the syringe barrel to pick up');
  pickup({ player, groundItemId: 33752, location: { x: 2315, y: 7418, z: 0 } });
  inventory.adds(33752, 1);
  click(61751, 2315, 7408);
  assert.equal(items.get(33756), 1, 'the south-east kitchen crate yields the venator stomach');
  click(61719, 2308, 7411, 'Inspect');
  assert.equal(items.get(33747), undefined, 'the sink asks before removing its plug');
  confirm();
  assert.equal(items.get(33747), 1, 'inspecting the kitchen sink yields its plug');
  click(61722, 2356, 7400, 'Inspect');
  assert.equal(prompt.title, 'The sink is empty.', 'the larder sink opens its native tap menu');
  choosePrompt('Turn the tap on');
  assert.equal(varbits.get(15537), 0, 'the tap drains away without a plug');
  useOn(33747, 61722, 2356, 7400);
  click(61722, 2356, 7400, 'Inspect');
  assert.equal(prompt.title, 'The sink is empty and the drain is plugged.');
  choosePrompt('Turn the tap on');
  assert.equal(varbits.get(15537), 2, 'the plugged sink collapses when the tap is turned on');
  click(61722, 2356, 7400, 'Inspect');
  assert.equal(prompt.title, 'Take the pipe?');
  assert.equal(items.get(33748), undefined, 'the broken pipe requires confirmation');
  confirm();
  assert.equal(items.get(33748), 1, 'the plugged sink collapses and yields its broken pipe');
  useOn(33748, 61726, 2360, 7403);
  assert.equal(items.get(33749), 1, 'the pipe retrieves the sharp knife from behind the cabinet');
  click(61751, 2358, 7397);
  assert.equal(items.get(33753), 1, 'the larder crate supplies the syringe plunger');
  useOn(33749, 61727, 2311, 7417);
  click(61727, 2311, 7417, 'Inspect');
  assert.equal(items.get(33750), 1, 'the opened venator corpse yields tongs');
  useOn(33750, 61719, 2308, 7411);
  assert.equal(items.get(33751), 1, 'the tongs retrieve the needle from the kitchen sink');
  useTogether(33752, 33753);
  assert.equal(items.get(33754), 1, 'the three parts assemble into an empty syringe');
  useTogether(33754, 33756);
  assert.equal(items.get(33755), 1, 'the syringe draws blood from the stomach');
  useOn(33755, 61683, 2308, 7415);
  click(61683, 2308, 7415);
  assert.equal(items.get(33734), undefined, 'the unlocked chest waits for the yes choice');
  confirm();
  assert.equal(items.get(33734), 1, 'the unlocked kitchen chest yields the left crest half');
  click(61741, 2579, 7382);
  assert.equal(prompt.options.length, 10, 'the armoury rack offers all four cache weapons and a leave option');
  prompt.options[1](); // sword
  assert.equal(items.get(33757), 1);
  click(61741, 2579, 7382);
  prompt.options[3](); // spear
  assert.equal(items.get(33758), 1, 'the recorded spare spear can be taken from the rack');
  click(61741, 2579, 7382);
  prompt.options[5](); // mace
  click(61741, 2579, 7382);
  prompt.options[7](); // battleaxe
  click(61741, 2579, 7382);
  prompt.options[5](); // second mace, as in the captured armoury puzzle
  useOn(33759, 61743, 2577, 7380);
  useOn(33760, 61744, 2569, 7386);
  useOn(33760, 61745, 2569, 7380);
  useOn(33757, 61742, 2565, 7386);
  assert.deepEqual([15545, 15546, 15547, 15548].map(id => varbits.get(id)), [1, 1, 1, 1],
    'the four cache varbits mark the correct mirrored weapons in place');
  click(61685, 2570, 7380);
  assert.equal(items.get(33735), 1, 'the completed statue arrangement unlocks the right crest half');
  useTogether(33734, 33735);
  assert.equal(items.get(33736), 1, 'the two crest halves combine');
  useOn(33736, 61665, 2358, 7386);
  assert.equal(varbits.get(15535), 1, 'placing the full crest opens the fireplace lock');
  assert.equal(prompt.title, 'Search the fireplace?');
  choosePrompt('No.');
  assert.equal(items.get(33728), undefined, 'declining leaves the new moon key in the fireplace');
  click(61665, 2358, 7386, 'Inspect');
  assert.equal(prompt.title, 'Search the fireplace?', 'the cache Inspect action lets the player return and search later');
  confirm();
  assert.equal(items.get(33728), 1, 'the fireplace gives the new moon key only after the player confirms the search');
  assert.equal(attrs.get('quest.the_blood_moon_rises.castle-story').newMoon.newMoonKeyClaimed, true);
});

test('Blood Moon throne door reaches and leaves the clipped ancient-shield crate pocket', () => {
  const { api, handlers } = mockApi();
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const quest = require('../plugins/quests/QuestRuntime').getRegisteredQuests()
    .filter(entry => entry.key === 'the_blood_moon_rises').at(-1);
  const attributes = new Map([
    ['quest.the_blood_moon_rises.castle-room', 3],
    ['quest.the_blood_moon_rises.castle-floor', 2],
  ]);
  const moved = [];
  const items = new Set([api.core.ItemIdentifiers.FULL_MOON_KEY]);
  const player = {
    getAttribute: key => attributes.get(key), setAttribute: (key, value) => attributes.set(key, value),
    getInventory: () => ({ contains: id => items.has(id) }),
    getPacketSender: () => new Proxy({}, { get: () => () => {} }),
    moveTo: location => moved.push([location.getX(), location.getY(), location.getZ()]),
    sendMessage() {},
  };
  quest.setStage(player, 40);
  const { RegionManager } = api.core;
  RegionManager.loadMapFiles(2306, 7397);
  RegionManager.loadMapFiles(2439, 7378);
  RegionManager.loadMapFiles(2434, 7372);
  const enter = handlers.objects.find(handler => handler.name === 'handleCastleDoorEnter');
  const route = handlers.routes.find(handler => handler.name === 'routeCastleDoorEnter');
  enter({ player, objectId: 61590, option: 'Enter',
    definition: { id: 61590, getName: () => 'Full moon door' },
    location: { x: 2306, y: 7397, z: 1 }, handled: false });
  assert.deepEqual(moved.at(-1), [2439, 7377, 0]);
  assert.equal(RegionManager.blocked(new api.core.Location(2439, 7377, 0), null), false);
  assert.ok(RegionManager.canMove(2439, 7377, 2439, 7376, 0, 1, 1, null));
  const returnRoute = { player, objectId: 61591, clickType: 1,
    definition: { id: 61591, getName: () => 'Full moon door', getInteractions: () => ['Enter'] },
    object: { getFace: () => 1, getLocation: () => new api.core.Location(2434, 7372, 0) },
    sourceLocation: { x: 2439, y: 7377, z: 0 }, destination: null };
  route(returnRoute);
  assert.deepEqual(returnRoute.destination, { x: 2439, y: 7377, z: 0 });
  enter({ player, objectId: 61591, option: 'Enter',
    definition: { id: 61591, getName: () => 'Full moon door' },
    location: { x: 2434, y: 7372, z: 0 }, handled: false });
  assert.deepEqual(moved.at(-1), [2306, 7396, 1]);
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-room'), 3);
});

