test('Blood Moon outer-library lever opens the captured portal to the throne parlour once', () => {
  const { api, handlers } = mockApi();
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const attributes = new Map([
    ['quest.the_blood_moon_rises.stage', 40],
    ['quest.the_blood_moon_rises.castle-room', 34],
    ['quest.the_blood_moon_rises.castle-floor', 2],
    ['quest.the_blood_moon_rises.castle-native-stage', 72],
  ]);
  const moved = [];
  const varbits = new Map();
  const messages = [];
  const player = {
    getAttribute: key => attributes.get(key), setAttribute: (key, value) => attributes.set(key, value),
    getInventory: () => ({ contains: () => false }),
    getPacketSender: () => new Proxy({ sendVarbit: (id, value) => varbits.set(id, value) },
      { get: (target, key) => target[key] ?? (() => {}) }),
    moveTo: location => moved.push([location.getX(), location.getY(), location.getZ()]),
    sendMessage: message => messages.push(message),
  };
  const lever = handlers.objects.find(handler => handler.name === 'handleCastleOuterLibraryLever');
  const portal = handlers.objects.find(handler => handler.name === 'handleCastleOuterLibraryPortal');
  assert.ok(lever && portal);
  assert.equal(portal({ player, objectId: 61771, definition: { id: 61771 },
    location: { x: 2450, y: 7372, z: 0 }, option: 'Enter', handled: false }), false,
  'the library Teleporter hook leaves other Castle teleporters to their own handlers');
  assert.equal(lever({ player, objectId: 61776, definition: { id: 61776 },
    location: { x: 2449, y: 7371, z: 0 }, option: 'Pull', handled: false }), false,
  'a different cache Lever falls through so its room-specific quest handler can run');
  const usePortal = () => {
    const event = { player, objectId: 61768, definition: { id: 61768 },
      location: { x: 2473, y: 7419, z: 0 }, option: 'Enter', handled: false };
    portal(event);
    return event;
  };
  assert.equal(usePortal().handled, true, 'the portal interaction is quest-owned even before unlock');
  assert.equal(moved.length, 0, 'the portal cannot skip the lever');
  const pull = { player, objectId: 61774, definition: { id: 61787 },
    location: { x: 2473, y: 7421, z: 0 }, option: 'Pull', handled: false };
  lever(pull);
  assert.equal(pull.handled, true);
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-story').parlourPortalUnlocked, true);
  assert.equal(varbits.get(15531), 1, 'the native castle varbit reveals the cache portal');
  assert.equal(varbits.get(15531), 1, 'the cache portal appears through its native unlock varbit');
  assert.match(messages.at(-1), /portal appears/);
  const enter = usePortal();
  assert.equal(enter.handled, true);
  assert.deepEqual(moved.at(-1), [2361, 7382, 0]);
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-room'), 7);
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-floor'), 1);
  assert.equal(varbits.get(15499), 7);
  assert.equal(varbits.get(15489), 1);
  assert.equal(varbits.get(15549), 1);
  assert.equal(varbits.get(15500), 2);
});

test('Blood Moon Castle basin puzzle requires all four correct potions before revealing the ancient symbol', () => {
  const { api, handlers } = mockApi();
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const { getRegisteredQuests } = require('../plugins/quests/QuestRuntime');
  const quest = getRegisteredQuests().filter((entry) => entry.key === 'the_blood_moon_rises').at(-1);
  const attributes = new Map();
  const counts = new Map();
  let freeSlots = 4;
  const inventory = {
    contains: (id) => (counts.get(id) ?? 0) > 0,
    getFreeSlots: () => freeSlots,
    adds(id, amount) { counts.set(id, (counts.get(id) ?? 0) + amount); return this; },
    deleteNumber: (id, amount) => counts.set(id, Math.max(0, (counts.get(id) ?? 0) - amount)),
  };
  const player = {
    getAttribute: (key) => attributes.get(key),
    setAttribute: (key, value) => attributes.set(key, value),
    getInventory: () => inventory,
    getSkillManager: () => ({ getMaxLevel: () => 99 }),
    getDialogueManager: () => ({ reset() {}, startDialogues() {} }),
    getPacketSender: () => new Proxy({}, { get: () => () => {} }),
    sendMessage() {},
  };
  quest.setStage(player, 40);
  const objects = handlers.objects;
  const shelves = objects.find((handler) => handler.name === 'handleCastleBasinPuzzle');
  const altar = objects.find((handler) => handler.name === 'handleBasinAltar');
  shelves({ player, definition: { getName: () => 'Shelves' }, location: { x: 2380, y: 7396, z: 0 }, handled: false });
  const I = api.core.ItemIdentifiers;
  for (const id of [I.CLOUDY_GREY_POTION, I.WEIGHTLESS_BLACK_POTION, I.THICK_RED_POTION, I.COLD_BLUISH_WHITE_POTION]) {
    assert.equal(inventory.contains(id), true, 'searching the shelves gives each distinct potion');
  }
  const pour = (itemId, objectId, x, y) => {
    const event = { player, itemId, objectId, location: { x, y, z: 0 }, handled: false };
    handlers.itemOnObject.find((handler) => handler.name === 'handleBasinPotion')(event);
    return event;
  };
  assert.equal(pour(I.CLOUDY_GREY_POTION, 61704, 2380, 7389).handled, true);
  assert.equal(inventory.contains(I.CLOUDY_GREY_POTION), true, 'a wrong basin keeps the potion');
  pour(I.THICK_RED_POTION, 61704, 2380, 7389);
  pour(I.WEIGHTLESS_BLACK_POTION, 61703, 2387, 7389);
  pour(I.CLOUDY_GREY_POTION, 61702, 2380, 7384);
  pour(I.COLD_BLUISH_WHITE_POTION, 61705, 2387, 7384);
  freeSlots = 0;
  altar({ player, definition: { getName: () => 'Altar' }, location: { x: 2382, y: 7393, z: 0 }, handled: false });
  assert.equal(inventory.contains(I.ANCIENT_SYMBOL), false, 'a full inventory leaves the symbol in the altar');
  assert.equal(attributes.get('quest.the_blood_moon_rises.castle-basin-puzzle').symbol, false);
  freeSlots = 1;
  altar({ player, definition: { getName: () => 'Altar' }, location: { x: 2382, y: 7393, z: 0 }, handled: false });
  assert.equal(inventory.contains(I.ANCIENT_SYMBOL), true, 'all four correctly poured potions reveal the symbol');
});

