test('Blood Moon Ivan preserves the four-slot supply handout until it fits', () => {
  const { api, handlers } = mockApi();
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const { getRegisteredQuests } = require('../plugins/quests/QuestRuntime');
  const quest = getRegisteredQuests().filter((entry) => entry.key === 'the_blood_moon_rises').at(-1);
  const attributes = new Map();
  const counts = new Map();
  const sentVarbits = [];
  let freeSlots = 3;
  const inventory = {
    getFreeSlots: () => freeSlots,
    contains: (id) => (counts.get(id) ?? 0) > 0,
    adds: (id, amount) => (counts.set(id, (counts.get(id) ?? 0) + amount), true),
    deleteNumber: (id, amount) => counts.set(id, Math.max(0, (counts.get(id) ?? 0) - amount)),
  };
  const player = {
    getAttribute: (key) => attributes.get(key),
    setAttribute: (key, value) => attributes.set(key, value),
    getInventory: () => inventory,
    getPacketSender: () => new Proxy({ sendVarbit: (id, value) => sentVarbits.push([id, value]) },
      { get: (target, key) => target[key] ?? (() => {}) }),
    sendMessage() {},
  };
  quest.setStage(player, 50);
  const action = handlers.custom.get('npc-dialogue:action').find((handler) => handler.name === 'onTranscriptAction');
  const claim = () => ({ player, kind: 'message', stepId: 'lvEeSL', handled: false, end: false });
  const blocked = claim();
  action(blocked);
  assert.equal(blocked.handled, true);
  assert.equal(blocked.end, true);
  assert.equal(attributes.get('quest.the_blood_moon_rises.blood-hunt')?.suppliesClaimed, undefined,
    'a full backpack does not consume Ivan’s availability flag');
  assert.equal(counts.size, 0);
  freeSlots = 4;
  const accepted = claim();
  action(accepted);
  assert.deepEqual([...counts.entries()].sort((a, b) => a[0] - b[0]), [
    [api.core.ItemIdentifiers.MYSTERIOUS_JERKY, 2],
    [api.core.ItemIdentifiers.PUTRID_STICKY_POTION_2_, 1],
    [api.core.ItemIdentifiers.FOUL_CHUNKY_POTION_3_, 1],
  ].sort((a, b) => a[0] - b[0]));
  assert.equal(attributes.get('quest.the_blood_moon_rises.blood-hunt').suppliesClaimed, true);
  assert.deepEqual(sentVarbits.find(([id]) => id === 15565), [15565, 0]);
  assert.deepEqual(sentVarbits.filter(([id]) => id === 15481).at(-1), [15481, 1],
    'the actual supply handover publishes the Quest Helper warning varbit');
  const duplicate = claim();
  action(duplicate);
  assert.equal(duplicate.end, true);
  assert.equal([...counts.values()].reduce((sum, count) => sum + count, 0), 4,
    'replaying the captured message cannot duplicate the supplies');
});

test('Blood Moon crossing preserves the captured native stages and starts the shared First Blood encounter', () => {
  const { api, handlers } = mockApi();
  const attributes = new Map();
  const sentVarbits = [];
  const graphics = [];
  const messages = [];
  let worldCycle = 100;
  const originalCycle = api.core.World.getProcessCycle;
  api.core.World.getProcessCycle = () => worldCycle;
  const spawns = [];
  let playerArea = null;
  const makeNpc = definition => {
    const npc = {
      definition, id: definition.id, hitpoints: 3000, maxHitpoints: 3000, area: null,
      isPlayer: () => false, isNpc: () => true, getAsNpc() { return this; },
      getIndex: () => 200 + spawns.length, setArea(area) { this.area = area; }, getArea() { return this.area; },
      getId() { return this.id; }, getHitpoints() { return this.hitpoints; },
      setMaxHitpoints(value) { this.maxHitpoints = value; }, setHitpoints(value) { this.hitpoints = value; },
      setMultiCombat() {}, setFlag(name, value = true) { this.flags ??= {}; this.flags[name] = value; },
      setScriptedMovement(value) { this.scriptedMovement = value; },
      getLocation: () => new api.core.Location(definition.x, definition.y, definition.z),
      getCombat: () => ({ attack(target) { npc.target = target; }, getLastAttack: () => ({ reset() {} }) }),
    };
    spawns.push(npc);
    return npc;
  };
  api.spawnNpc = makeNpc;
  api.removeNpc = npc => { npc.removed = true; };
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const quest = require('../plugins/quests/QuestRuntime').getRegisteredQuests()
    .filter(entry => entry.key === 'the_blood_moon_rises').at(-1);
  const player = {
    getAttribute: key => attributes.get(key), setAttribute: (key, value) => attributes.set(key, value),
    isPlayer: () => true, isNpc: () => false, getAsPlayer() { return this; }, getIndex: () => 100,
    getArea: () => playerArea, setArea: area => { playerArea = area; }, getUsername: () => 'first-blood-fixture',
    getInventory: () => ({ contains: () => false }), getHitpoints: () => 99,
    getLocation: () => player.location, getPrayerActive: () => [],
    moveTo: location => { player.location = location; },
    getPacketSender: () => new Proxy({
      sendVarbit: (id, value) => sentVarbits.push([id, value]),
      sendGraphic: (graphic, location) => graphics.push([graphic.getId(), location.getX(), location.getY(), location.getZ()]),
    },
      { get: (target, key) => target[key] ?? (() => {}) }),
    sendMessage: message => messages.push(message),
  };
  quest.setStage(player, 50);
  attributes.set('quest.the_blood_moon_rises.blood-hunt', { drawbridgeRepaired: true });
  const action = handlers.custom.get('npc-dialogue:action').find(handler => handler.name === 'onTranscriptAction');
  action({ player, stepId: 'lKvIyH' });
  assert.deepEqual(sentVarbits.at(-1), [15464, 88]);
  action({ player, stepId: 'D5qF0g' });
  assert.deepEqual(sentVarbits.at(-1), [15464, 88]);
  action({ player, stepId: 'sw9z49' });
  assert.deepEqual(sentVarbits.at(-1), [15464, 90]);
  const boss = spawns.find(npc => npc.id === api.core.NpcIdentifiers.LOWERNIEL_DRAKAN_20);
  assert.ok(boss, 'the captured first-form Lowerniel is spawned at the recorded battle action');
  assert.equal(boss.maxHitpoints, 3000);
  assert.equal(boss.hitpoints, 3000);
  assert.equal(playerArea, attributes.get('quest.the_blood_moon_rises.first-blood-area'));
  assert.deepEqual([player.location.getX(), player.location.getY(), player.location.getZ()], [2712, 7840, 0]);
  const area = attributes.get('quest.the_blood_moon_rises.first-blood-area');
  const vanescula = spawns.find(npc => npc.id === api.core.NpcIdentifiers.VANESCULA_DRAKAN_20);
  assert.equal(boss.target, vanescula, 'Lowerniel initially focuses Vanescula during the first spear-lunge sequence');
  assert.equal(boss.flags['combat:no-retaliate'], true, 'early player hits cannot retarget Lowerniel from Vanescula');
  assert.equal(boss.scriptedMovement, undefined,
    'First Blood leaves Lowerniel on the normal NPC combat path instead of pausing scripted movement each tick');
  try {
    worldCycle = 102;
    area.process(boss);
    const hitModifier = handlers.npcHitModify.find(handler => handler.name === 'handleFirstBloodHit');
    let damage = 20;
    const hit = { getHits: () => [{ getDamage: () => damage, setDamage: value => { damage = value; } }], updateTotalDamage() {} };
    hitModifier({ npc: boss, attacker: player, hit });
    assert.equal(damage, 0, 'player hits cannot bypass the initial lunge-dodge mechanic');
    damage = 69;
    const allyHit = { getHits: () => [{ getDamage: () => damage, setDamage: value => { damage = value; } }], updateTotalDamage() {} };
    hitModifier({ npc: vanescula, attacker: boss, hit: allyHit });
    assert.equal(damage, 0, 'Lowerniel cannot remove the ally before the opening dodge sequence ends');
    for (let dodge = 0; dodge < 3; dodge++) {
      if (dodge > 0) { worldCycle += 2; area.process(boss); }
      assert.ok(messages.at(-1)?.includes('sparkling safe tile'),
        'each lunge tells the player to follow the visible safe-tile mark');
      assert.equal(graphics.length, dodge + 1, 'one safe-tile mark is sent for each lunge');
      const [graphicId, x, y, z] = graphics.at(-1);
      assert.ok([3896, 3897].includes(graphicId), 'a cache-verified Lowerniel safe-tile graphic is sent');
      assert.ok(x >= 2688 && x <= 2735 && y >= 7810 && y <= 7880,
        'the marked tile stays inside the fight arena');
      const marked = new api.core.Location(x, y, z);
      assert.equal(Math.max(Math.abs(x - player.location.getX()), Math.abs(y - player.location.getY())), 1,
        'a safe mark is one reachable step away');
      assert.equal(api.core.RegionManager.blocked(marked, area), false, 'the marked tile is collision-clear');
      assert.equal(api.core.RegionManager.canMove(player.location.getX(), player.location.getY(), x, y, z, 1, 1, area),
        true, 'the safe-tile mark is reachable from the player');
      player.location = marked;
      worldCycle += 2;
      area.process(boss);
    }
    assert.equal(boss.target, player, 'three successful spear-lunge dodges make Lowerniel focus the player');
    assert.equal(boss.flags['combat:no-retaliate'], false, 'Lowerniel can retaliate after the opening sequence');
    damage = 20;
    hitModifier({ npc: boss, attacker: player, hit });
    assert.equal(damage, 20, 'player damage becomes available after the lunge sequence');
    boss.hitpoints = 2899;
    player.location = new api.core.Location(2712, 7840, 0);
    worldCycle += 2;
    area.process(boss);
    assert.equal(graphics.length, 3, 'safe sparkles disappear once Lowerniel passes 2,900 HP');
    assert.match(messages.at(-1), /telegraph points (north|east|south|west)/,
      'the boss thrust animation and direction message remain as the cue without sparkles');
  } finally { api.core.World.getProcessCycle = originalCycle; }
});

test('Blood Moon post-breach chapter restores actors and follows the captured native 124–136 handoff', () => {
  const { api, handlers } = mockApi();
  const emittedEvents = [];
  const emitCustomEvent = api.emitCustomEvent;
  api.emitCustomEvent = (name, payload) => {
    emittedEvents.push(name);
    emitCustomEvent(name, payload);
  };
  const npcTalkHooks = [];
  api.onAnyNpcInteraction = hook => npcTalkHooks.push(hook);
  const attributes = new Map();
  const sentVarbits = [];
  const spawned = [];
  api.spawnNpc = spec => {
    const npc = { ...spec, getId: () => spec.id, isDestroyed: () => false };
    spawned.push(npc);
    return npc;
  };
  api.removeNpc = npc => { npc.removed = true; };
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const quest = require('../plugins/quests/QuestRuntime').getRegisteredQuests()
    .filter(entry => entry.key === 'the_blood_moon_rises').at(-1);
  const player = {
    getAttribute: key => attributes.get(key), setAttribute: (key, value) => attributes.set(key, value),
    getPacketSender: () => new Proxy({ sendVarbit: (id, value) => sentVarbits.push([id, value]) },
      { get: (target, key) => target[key] ?? (() => {}) }),
    moveTo: location => { player.location = location; }, getInventory: () => ({ contains: () => false }),
    getDialogueManager: () => ({ reset() {}, startDialogues() {}, getCurrent() { return undefined; } }),
    sendMessage() {},
  };
  quest.setStage(player, 80);
  assert.equal(quest.varbitValue(80, player), 124,
    'the internal Theatre stage begins at the captured post-breach native value');
  handlers.custom.get('player:bootstrap-complete')
    .find(handler => handler.name === 'syncTheatreActorsAfterBootstrap')({ player });
  assert.deepEqual(spawned.map(npc => [npc.id, npc.x, npc.y]), [[15855, 3606, 3416]],
    'the owner-only Ivan actor is restored after relog at the captured Haunted Woods tile');

  const action = handlers.custom.get('npc-dialogue:action')
    .find(handler => handler.name === 'onTranscriptAction');
  action({ player, stepId: '1JPVz5' });
  assert.equal(quest.varbitValue(80, player), 126);
  const line = handlers.custom.get('npc-dialogue:line')
    .find(handler => handler.name === 'onBloodMoonDialogueLine');
  const finalIvanLine = { player, text: "We'd better get over there then.", step: { speaker: 'Ivan Strom' } };
  line(finalIvanLine);
  finalIvanLine.after();
  assert.deepEqual([player.location.getX(), player.location.getY(), player.location.getZ()], [3491, 9628, 0]);
  assert.equal(quest.varbitValue(80, player), 128);
  assert.deepEqual(spawned.slice(1).map(npc => [npc.id, npc.x, npc.y]), [
    [15855, 3492, 9626], [15872, 3493, 9628], [15955, 3494, 9627],
  ]);
  action({ player, kind: 'message', stepId: 'gEkhma' });
  assert.equal(quest.varbitValue(80, player), 130,
    'the recorded Veliaf/Ivan departure advances the substage without changing internal chapter 80');
  const chapterLine = text => {
    const event = { player, text };
    line(event);
    event.after?.();
  };
  chapterLine('The situation here in Hallowvale is... delicate, my child. To avoid attention, I would suggest we travel to Ver Sinhaza separately.');
  assert.equal(quest.varbitValue(80, player), 132);
  assert.deepEqual(spawned.at(-1) && [spawned.at(-1).id, spawned.at(-1).x, spawned.at(-1).y],
    [15956, 3670, 3219],
    'the saved Ver Sinhaza substage restores its owner-only Sugadinti actor at the captured tile');
  chapterLine('Alright. I can do that.');
  assert.equal(quest.varbitValue(80, player), 134);
  chapterLine('Then let us begin, my child.');
  assert.equal(quest.varbitValue(80, player), 136);
  assert.deepEqual([spawned.at(-1).id, spawned.at(-1).x, spawned.at(-1).y], [15956, 3670, 3219],
    'Sugadinti remains available outside the Theatre if the player escapes before finishing the raid');
  const retryTalk = { player, npcId: 15956, definition: { getName: () => 'Sugadinti Vitur' }, option: 'Talk-to' };
  assert.equal(npcTalkHooks.at(-1)['Talk-to'](retryTalk), true,
    'at native136, an unstarted encounter still opens the first outside-Theatre conversation');
  attributes.set('quest.the_blood_moon_rises.tob-challenge', { started: true, completed: false });
  retryTalk.handled = false;
  assert.equal(npcTalkHooks.at(-1)['Talk-to'](retryTalk), true,
    'talking to Sugadinti after leaving selects the captured retry conversation');
  assert.equal(retryTalk.handled, true);
  handlers.custom.get('npc-dialogue:choice').find(handler => handler.name === 'onChoice')({
    player, option: "I'm ready.",
  });
  assert.ok(emittedEvents.includes('tob:bmr-start'), 'the retry choice re-enters the same BMR encounter');
  assert.deepEqual(sentVarbits.slice(-6), [
    [15464, 126], [15464, 128], [15464, 130], [15464, 132], [15464, 134], [15464, 136],
  ]);
});

test('Blood Moon resumes the saved native-96 fleeing scene after logout', () => {
  const { api, handlers } = mockApi();
  const lines = [];
  const emit = api.emitCustomEvent;
  api.emitCustomEvent = (name, event) => {
    if (name === 'npc-dialogue:line') lines.push(event);
    return emit(name, event);
  };
  const attributes = new Map();
  const varbits = [];
  let dialogueStarted = false;
  const player = {
    getAttribute: key => attributes.get(key), setAttribute: (key, value) => attributes.set(key, value),
    getInventory: () => ({ contains: () => false }),
    getPacketSender: () => ({ sendVarbit: (id, value) => varbits.push([id, value]), sendQuestList() {},
      sendInterfaceFlagsRange() {}, sendConfig() {} }),
    getDialogueManager: () => ({ reset() {}, startDialogues() { dialogueStarted = true; } }),
    getLocation: () => new api.core.Location(2730, 7852, 0),
    moveTo(location) { this.location = location; },
  };
  require('../plugins/quests/quests/TheBloodMoonRises.Quest')(api);
  const quest = require('../plugins/quests/QuestRuntime').getRegisteredQuests()
    .filter(entry => entry.key === 'the_blood_moon_rises').at(-1);
  quest.setStage(player, 50);
  attributes.set('quest.the_blood_moon_rises.blood-hunt', {
    firstBloodThresholdReached: true, firstBloodDefeated: true, nativeStage: 96,
  });
  handlers.playerLogin.find(handler => handler.name === 'recoverFirstBloodEncounter')({ player });
  assert.equal(dialogueStarted, true, 'the missing post-fight transcript resumes on login');

  const action = handlers.custom.get('npc-dialogue:action').find(handler => handler.name === 'onTranscriptAction');
  action({ player, stepId: 'kfvYPl' });
  assert.equal(quest.getStage(player), 50, 'the Sunspear ambush is still part of the woodland chapter');
  assert.equal(attributes.get('quest.the_blood_moon_rises.blood-hunt').nativeStage, 98);
  action({ player, stepId: '0I1l4O' });
  assert.equal(attributes.get('quest.the_blood_moon_rises.blood-hunt').nativeStage, 98);
  assert.equal(quest.getStage(player), 60, 'the woodland handoff starts Hallowed preparations');
  assert.equal(attributes.get('quest.the_blood_moon_rises.preparations').introStarted, true);
  assert.equal(lines.findLast(event => event.step.speaker === 'Mysterious Woman').npcId, api.core.NpcIdentifiers.MYSTERIOUS_WOMAN,
    'the preparation intro uses its actual speaker instead of NPC zero');
  assert.deepEqual(varbits.at(-1), [15464, 98]);
  assert.deepEqual([player.location.getX(), player.location.getY(), player.location.getZ()], [2987, 7699, 0]);
  action({ player, stepId: 'P8i6Tl' });
  assert.deepEqual([player.location.getX(), player.location.getY(), player.location.getZ()], [3168, 7830, 1]);
  const line = handlers.custom.get('npc-dialogue:line').find(handler => handler.name === 'onBloodMoonDialogueLine');
  const endIntro = { player, step: { speaker: 'Efaritay Hallow' },
    text: 'Now, let us get to work.' };
  line(endIntro);
  assert.equal(typeof endIntro.after, 'function');
  endIntro.after();
  assert.equal(attributes.get('quest.the_blood_moon_rises.preparations').introComplete, true);
  assert.deepEqual(varbits.at(-1), [15464, 100]);
  const startGathering = { player, step: { player: true }, text: "Alright, I'll get to it." };
  line(startGathering);
  assert.equal(typeof startGathering.after, 'function');
  startGathering.after();
  assert.equal(attributes.get('quest.the_blood_moon_rises.preparations').gatherStarted, true);
  assert.ok(varbits.some(([id, value]) => id === 15464 && value === 102),
    'the captured player reply reveals the Amitire plant for gathering');
});

