test('Song of the Elves gives the real stackable explosive potion with one free slot', () => {
  const { api, handlers } = mockApi();
  const areas = [];
  const items = new Map();
  let freeSlots = 1;
  api.registerArea = (area) => {
    areas.push(area);
    area.enter = (character) => { character.setArea(area); };
  };
  const runtime = require('../plugins/quests/QuestRuntime');
  const originalStartTranscript = runtime.startTranscript;
  let supplySteps;
  const playedVariants = [];
  runtime.startTranscript = (_api, _player, _npc, _page, variant, select) => {
    playedVariants.push(variant);
    if (variant === 'preparations-at-the-dwarf-camp-talking-to-elena-after-talking-to-baxtorian') {
      const raw = require('../data/definitions/npc-dialogues.json')['Song of the Elves'].variants[variant];
      supplySteps = select(raw);
    }
    return true;
  };
  try { require('../plugins/quests/quests/SongOfTheElves.Quest')(api); }
  finally { runtime.startTranscript = originalStartTranscript; }
  const quest = require('../plugins/quests/QuestRuntime').getRegisteredQuests()
    .filter((entry) => entry.key === 'song_of_the_elves').at(-1);
  const talkBaxtorian = handlers.npcInteractions.get('Baxtorian')['Talk-to'];
  const talkElena = handlers.npcInteractions.get('Elena')['Talk-to'];
  const attributes = new Map();
  const inventory = {
    getAmount: (id) => items.get(id) ?? 0,
    getFreeSlots: () => freeSlots,
    adds: (id, amount) => { if (!items.has(id)) freeSlots--; items.set(id, (items.get(id) ?? 0) + amount); },
  };
  const player = {
    getUsername: () => 'DwarfCampStackablePotionTest',
    getAttribute: (key) => attributes.get(key),
    setAttribute: (key, value) => attributes.set(key, value),
    getInventory: () => inventory,
    getArea: () => player.area ?? null,
    setArea(area) { player.area = area; },
    moveTo(location) { player.location = location; },
    getLocation: () => player.location,
    getIndex: () => 1,
    getPacketSender: () => new Proxy({}, { get: () => () => {} }),
    sendMessage: (message) => (player.messages ??= []).push(message),
    isPlayer: () => true,
    isNpc: () => false,
    getAsPlayer: () => player,
  };
  quest.setStage(player, 180);
  const baxtorian = { getName: () => 'Baxtorian' };
  const elena = { getName: () => 'Elena' };
  talkBaxtorian({ player, npcId: api.core.NpcIdentifiers.BAXTORIAN, option: 'Talk-to', definition: baxtorian, target: baxtorian });
  assert.ok(player.getArea(), 'the normal Baxtorian interaction brings the player to the camp');
  talkElena({ player, npcId: api.core.NpcIdentifiers.ELENA, option: 'Talk-to', definition: elena, target: elena });
  const potion = api.core.ItemIdentifiers.EXPLOSIVE_POTION_3;
  assert.equal(potion, 23818);
  assert.equal(items.get(potion), undefined, 'Elena hands over the potions at the offer in her conversation');
  assert.ok(JSON.stringify(supplySteps).includes('gBRsQm'));
  assert.equal(JSON.stringify(supplySteps).includes('4Q1iXL'), false, 'the full-bag prose cannot override this supply branch');
  assert.equal(player.messages?.some((message) => message.includes('one inventory space')), false);

  const supplyMessage = { player, kind: 'message', stepId: 'gBRsQm' };
  handlers.custom.get('npc-dialogue:action').find(handler => handler.name === 'onAction')(supplyMessage);
  assert.equal(freeSlots, 0);
  assert.notEqual(supplyMessage.handled, true, 'the dialogue continues after the stack uses the last slot');
  assert.deepEqual(supplyMessage.box, { items: [potion] });
  assert.equal(items.get(potion), 7, 'the transcript does not duplicate the supply already handed over');
  assert.equal(player.messages?.some(message => message.includes('one empty inventory slot')), false);
  talkElena({ player, npcId: api.core.NpcIdentifiers.ELENA, option: 'Talk-to', definition: elena, target: elena });
  handlers.custom.get('npc-dialogue:action').find(handler => handler.name === 'onAction')({ player, kind: 'message', stepId: 'gBRsQm' });
  assert.equal(items.get(potion), 7, 'reopening the conversation with a full bag preserves the existing stack');

  items.clear();
  freeSlots = 0;
  talkElena({ player, npcId: api.core.NpcIdentifiers.ELENA, option: 'Talk-to', definition: elena, target: elena });
  assert.equal(items.size, 0, 'a full inventory still preserves the supply instead of silently dropping it');
  assert.ok(player.messages?.some((message) => message.includes('one inventory space')));

  attributes.set('quest.song_of_the_elves.camp-holes', 127);
  attributes.set('quest.song_of_the_elves.late-chapter', 18);
  quest.setStage(player, 190);
  handlers.custom.get('npc-dialogue:choice').find(h => h.name === 'handleDialogueChoice')({
    player, option: "I'm ready.", definition: baxtorian,
  });
  assert.equal(attributes.get('quest.song_of_the_elves.camp-defense'), undefined,
    'the four-minute timer and attackers wait while the meeting plays');
  assert.equal(playedVariants.includes('sealing-the-underground-pass-meeting-with-lord-iorwerth'), false,
    'the choice must finish its Baxtorian branch before opening the next conversation');
  const departure = { player, text: 'Then we will leave at once.' };
  handlers.custom.get('npc-dialogue:line').find(h => h.name === 'finishCampMeetingLine')(departure);
  assert.equal(typeof departure.after, 'function');
  departure.after();
  assert.ok(playedVariants.includes('sealing-the-underground-pass-meeting-with-lord-iorwerth'));
  const finalLine = { player, text: 'As am I.' };
  handlers.custom.get('npc-dialogue:line').find(h => h.name === 'finishCampMeetingLine')(finalLine);
  assert.equal(attributes.get('quest.song_of_the_elves.camp-defense'), undefined,
    'holding the final speech does not start the attack');
  assert.equal(typeof finalLine.after, 'function');
  finalLine.after();
  const endsAt = attributes.get('quest.song_of_the_elves.camp-defense');
  assert.equal(endsAt, api.core.World.getProcessCycle() + 400);
  finalLine.after();
  assert.equal(attributes.get('quest.song_of_the_elves.camp-defense'), endsAt,
    'repeated continuation does not restart the timer');
});

