test('Song of the Elves Fragment uses Wiki paired ranged hits and ordered phase-scaled specials', () => {
  const { api, handlers } = mockApi();
  const originalCycle = api.core.World.getProcessCycle;
  const runtime = require('../plugins/quests/QuestRuntime');
  const originalStartTranscript = runtime.startTranscript;
  let cycle = 100;
  const queued = [];
  const attributes = new Map([
    ['quest.song_of_the_elves.late-chapter', 19],
    ['quest.song_of_the_elves.camp-battle', true],
    ['quest.song_of_the_elves.fragment-defeated', false],
  ]);
  const activePrayers = [];
  const playerMessages = [];
  const playerCombat = {
    getLastAttack: () => ({ reset() {} }),
    getHitQueue: () => ({ addPendingDamage: hits => queued.push(...hits) }),
  };
  const player = {
    getUsername: () => 'FragmentPrayerTest',
    getAttribute: key => attributes.get(key),
    setAttribute: (key, value) => attributes.set(key, value),
    getInventory: () => ({ getFreeSlots: () => 10, getAmount: () => 0, adds() {} }),
    getArea: () => player.area ?? null,
    setArea(area) { player.area = area; },
    moveTo() {},
    getLocation: () => ({ getDistance: () => 10 }),
    getIndex: () => 1,
    getCombat: () => playerCombat,
    getPrayerActive: () => activePrayers,
    getSkillManager: () => ({ getMaxLevel: () => 99, getCurrentLevel: () => 99 }),
    sendMessage(message) { playerMessages.push(message); },
    getPacketSender: () => new Proxy({}, { get: () => () => {} }),
    isPlayer: () => true,
    isNpc: () => false,
    getAsPlayer: () => player,
  };
  let boss;
  const spawned = [];
  let addAttackResets = 0;
  let nextNpcIndex = 2;
  api.registerArea = () => {};
  api.removeNpc = npc => { npc.removed = true; };
  api.spawnNpc = definition => {
    const npc = {
      id: definition.id,
      index: nextNpcIndex++,
      area: null,
      hitpoints: 1000,
      maxHitpoints: 1000,
      getIndex: () => npc.index,
      getArea: () => npc.area,
      setArea(area) { npc.area = area; },
      setMultiCombat() {},
      setMaxHitpoints(value) { npc.maxHitpoints = value; },
      setHitpoints(value) { npc.hitpoints = value; },
      getHitpoints: () => npc.hitpoints,
      getMaxHitpoints: () => npc.maxHitpoints,
      setScriptedMovement(value) { npc.scriptedMovement = value; },
      getCurrentDefinition: () => ({ getAttackSpeed: () => 7 }),
      getCombat: () => ({ getLastAttack: () => ({ reset() { addAttackResets++; } }) }),
      getLocation: () => ({ getDistance: () => 10 }),
      sendMessage() {},
      isRegistered: () => false,
      isPlayer: () => false,
      isNpc: () => true,
      getAsNpc() { return npc; },
    };
    if (!boss) boss = npc;
    spawned.push(npc);
    return npc;
  };
  api.core.World.getProcessCycle = () => cycle;
  runtime.startTranscript = () => true;
  try {
    require('../plugins/quests/quests/SongOfTheElves.Quest')(api);
    const quest = runtime.getRegisteredQuests().filter(entry => entry.key === 'song_of_the_elves').at(-1);
    quest.setStage(player, 190);
    handlers.custom.get('npc-dialogue:action').at(-1)({ player, stepId: 'xfnkES', handled: false });
    assert.equal(boss.scriptedMovement, true, 'the manually driven encounter cannot also use default NPC combat');
    const area = player.getArea();
    assert.equal(area.npcAggression(player, boss), false,
      'the prayer-aware area controller owns the boss attack cycle');

    activePrayers[api.core.PrayerHandler.PROTECT_FROM_MISSILES] = true;
    const originalRandom = Math.random;
    Math.random = () => 0.999999;
    try {
      cycle = 107;
      area.process(boss);
      assert.equal(queued.length, 2);
      assert.equal(queued[0].getDamage(), 3, 'Protect from Missiles reduces the first 12-damage projectile to 3');
      assert.equal(queued[1].getDamage(), 2, 'the second projectile is the same damage or one lower');

      activePrayers[api.core.PrayerHandler.PROTECT_FROM_MISSILES] = false;
      cycle = 114;
      area.process(boss);
      assert.equal(queued.length, 4);
      assert.equal(queued[2].getDamage(), 12, 'without the overhead, the first projectile deals 12');
      assert.equal(queued[3].getDamage(), 11, 'the second projectile deals the same or one less');
    } finally {
      Math.random = originalRandom;
    }

    const originalRandomForBlast = Math.random;
    Math.random = () => 0;
    try {
      for (const [bossHp, expectedDamage] of [[1000, 94], [600, 96], [300, 98]]) {
        player.getArea().leave(player, false);
        boss = null;
        cycle += 100;
        queued.length = 0;
        handlers.custom.get('npc-dialogue:action').at(-1)({ player, stepId: 'xfnkES', handled: false });
        const area = player.getArea();
        boss.hitpoints = bossHp;
        const startCycle = cycle;
        activePrayers[api.core.PrayerHandler.PROTECT_FROM_MISSILES] = true;
        let blastDamage = [];
        for (let offset = 1; offset <= 89; offset++) {
          cycle = startCycle + offset;
          if (offset === 86) boss.hitpoints = bossHp;
          queued.length = 0;
          area.process(boss);
          if (offset === 87) blastDamage = queued.map(hit => hit.getDamage());
        }
        assert.ok(blastDamage.includes(expectedDamage),
          `the unavoidable blast leaves ${expectedDamage} damage at boss HP ${bossHp}; saw ${blastDamage}`);
      }
    } finally {
      Math.random = originalRandomForBlast;
    }

    const originalRandomForAdds = Math.random;
    Math.random = () => 0;
    try {
      player.getArea().leave(player, false);
      boss = null;
      cycle += 100;
      const spawnStart = spawned.length;
      handlers.custom.get('npc-dialogue:action').at(-1)({ player, stepId: 'xfnkES', handled: false });
      const area = player.getArea();
      const startCycle = cycle;
      for (let offset = 1; offset <= 36; offset++) {
        cycle = startCycle + offset;
        area.process(boss);
      }
      const clones = spawned.slice(spawnStart + 1);
      assert.equal(clones.length, 2);
      assert.equal(clones[0].id, api.core.NpcIdentifiers.FRAGMENT_OF_SEREN,
        'cache 8917 has the lighter ambient used for the true echo');
      assert.equal(clones[1].id, api.core.NpcIdentifiers.FRAGMENT_OF_SEREN_2,
        'cache 8918 has the darker ambient used for the false echo');
      assert.ok(clones.every(npc => npc.scriptedMovement), 'scripted echoes cannot run the normal NPC combat AI');
      assert.ok(clones.every(npc => area.npcAggression(player, npc) === false),
        'echoes cannot acquire a second, generic combat target');
      const resetsBeforeAddTick = addAttackResets;
      cycle += 1;
      area.process(clones[0]);
      assert.ok(addAttackResets > resetsBeforeAddTick, 'the area prevents generic NPC regeneration during scripted phases');

      for (let offset = 37; offset <= 60; offset++) {
        cycle = startCycle + offset;
        area.process(boss);
      }
      const firstPhaseBeams = spawned.filter(npc => npc.id === api.core.NpcIdentifiers.COL_00FFFF_CRYSTAL_WHIRLWIND_COL &&
        npc.index > clones.at(-1).index);
      assert.equal(firstPhaseBeams.length, 2, 'the first phase uses two healing beams');
      assert.ok(firstPhaseBeams.every(npc => npc.scriptedMovement), 'scripted beams cannot run the normal NPC combat AI');
      assert.ok(firstPhaseBeams.every(npc => area.npcAggression(player, npc) === false),
        'beams cannot acquire a second, generic combat target');
      boss.hitpoints = 500;
      for (let offset = 61; offset <= 68; offset++) {
        cycle = startCycle + offset;
        area.process(boss);
        const expectedHp = offset < 64 ? 500 : offset < 68 ? 508 : 516;
        assert.equal(boss.hitpoints, expectedHp,
          `two live beams heal 4 HP each on the four-tick cadence (offset ${offset})`);
      }
      firstPhaseBeams[0].hitpoints = 0;
      cycle = startCycle + 72;
      area.process(boss);
      assert.equal(boss.hitpoints, 520, 'a defeated beam stops healing before its delayed NPC death event');
      firstPhaseBeams[1].hitpoints = 0;
      cycle = startCycle + 76;
      area.process(boss);
      assert.equal(boss.hitpoints, 520, 'defeated beams cannot heal while their death animations finish');
      firstPhaseBeams.forEach(npc => { npc.hitpoints = 1; });
      const missedMagicRoll = {
        attacker: player,
        target: firstPhaseBeams[0],
        combatType: api.core.CombatType.MAGIC,
        forceAccurate: false,
      };
      for (const hook of handlers.combatHitRoll) hook(missedMagicRoll);
      assert.equal(missedMagicRoll.forceAccurate, true,
        'a magic splash cannot leave an OSRS one-hit beam alive to heal the boss');
      const missedTrueEchoRoll = { attacker: player, target: clones[0], combatType: api.core.CombatType.MAGIC,
        forceAccurate: false };
      const missedFalseEchoRoll = { attacker: player, target: clones[1], combatType: api.core.CombatType.MAGIC,
        forceAccurate: false };
      for (const hook of handlers.combatHitRoll) {
        hook(missedTrueEchoRoll);
        hook(missedFalseEchoRoll);
      }
      assert.equal(missedTrueEchoRoll.forceAccurate, true,
        'the randomized lighter echo must be hittable before its brief phase expires');
      assert.equal(missedFalseEchoRoll.forceAccurate, false, 'false echoes keep their normal invalid-target behavior');
      for (const beam of firstPhaseBeams) area.process(beam);
      const missedPart = { damage: 0, getDamage() { return this.damage; }, setDamage(value) { this.damage = value; } };
      let totalDamage = 0;
      handlers.npcHitModify.at(-1)({
        npc: firstPhaseBeams[0],
        hit: {
          getAttacker: () => player,
          getHits: () => [missedPart],
          updateTotalDamage() { totalDamage = missedPart.damage; },
        },
      });
      assert.equal(missedPart.damage, 1, 'any attack kills a one-hit whirlwind, even if its hit roll missed');
      assert.equal(totalDamage, 1);
      const missedEchoPart = { damage: 0, getDamage() { return this.damage; }, setDamage(value) { this.damage = value; } };
      let echoDamage = 0;
      handlers.npcHitModify.at(-1)({
        npc: clones[0],
        hit: {
          getAttacker: () => player,
          getHits: () => [missedEchoPart],
          updateTotalDamage() { echoDamage = missedEchoPart.damage; },
        },
      });
      assert.equal(missedEchoPart.damage, 1, 'any attack destroys the true echo, even if its original roll missed');
      assert.equal(echoDamage, 1);
      const falseEchoPart = { damage: 12, getDamage() { return this.damage; }, setDamage(value) { this.damage = value; } };
      handlers.npcHitModify.at(-1)({
        npc: clones[1],
        hit: {
          getAttacker: () => player,
          getHits: () => [falseEchoPart],
          updateTotalDamage() {},
        },
      });
      assert.equal(falseEchoPart.damage, 0, 'false echoes remain unhittable');
      handlers.npcDeath.at(-1)({ npc: clones[0], killer: player });

      for (const [bossHp, expectedAdds, expectedBlast] of [[500, 3, 96], [300, 4, 98]]) {
        player.getArea().leave(player, false);
        boss = null;
        cycle += 100;
        const phaseStart = spawned.length;
        handlers.custom.get('npc-dialogue:action').at(-1)({ player, stepId: 'xfnkES', handled: false });
        const phaseArea = player.getArea();
        boss.hitpoints = bossHp;
        const phaseCycle = cycle;
        const phaseSpecialTicks = [];
        for (let offset = 1; offset <= 36; offset++) {
          cycle = phaseCycle + offset;
          const beforeMessages = playerMessages.length;
          phaseArea.process(boss);
          for (const message of playerMessages.slice(beforeMessages)) {
            if (message.includes('teleports you beside')) phaseSpecialTicks.push([offset, 'teleport']);
            else if (message.includes('follow-up strike')) phaseSpecialTicks.push([offset, 'follow-up']);
            else if (message.includes('divides into')) phaseSpecialTicks.push([offset, 'clones']);
          }
        }
        const phaseClones = spawned.slice(phaseStart + 1);
        assert.equal(phaseClones.length, expectedAdds, `boss HP ${bossHp} uses ${expectedAdds} total echoes`);
        assert.ok(playerMessages.includes(`The Fragment divides into ${expectedAdds} echoes. Strike the true echo; the false ones cannot be harmed.`));
        handlers.npcDeath.at(-1)({ npc: phaseClones[0], killer: player });
        for (let offset = 37; offset <= 60; offset++) {
          cycle = phaseCycle + offset;
          const beforeMessages = playerMessages.length;
          phaseArea.process(boss);
          for (const message of playerMessages.slice(beforeMessages)) {
            if (message.includes('Crystal Whirlwinds surround')) phaseSpecialTicks.push([offset, 'beams']);
          }
        }
        const phaseBeams = spawned.filter(npc => npc.id === api.core.NpcIdentifiers.COL_00FFFF_CRYSTAL_WHIRLWIND_COL &&
          npc.index > phaseClones.at(-1).index);
        assert.equal(phaseBeams.length, expectedAdds, `boss HP ${bossHp} uses ${expectedAdds} healing beams`);
        for (let offset = 61; offset <= 87; offset++) {
          cycle = phaseCycle + offset;
          if (offset === 86) boss.hitpoints = bossHp;
          queued.length = 0;
          const beforeMessages = playerMessages.length;
          phaseArea.process(boss);
          for (const message of playerMessages.slice(beforeMessages)) {
            if (message.includes('devastating burst')) phaseSpecialTicks.push([offset, 'blast']);
          }
        }
        assert.deepEqual(phaseSpecialTicks, [[12, 'teleport'], [12 + ({ 500: 3, 300: 2 }[bossHp]), 'follow-up'],
          [36, 'clones'], [60, 'beams'], [84, 'blast']],
        `boss HP ${bossHp} follows teleport → clones → beams → blast at phase timing`);
        assert.ok(phaseBeams.every(beam => beam.removed), 'the beams disappear before the blast resolves');
        assert.ok(queued.some(hit => hit.getDamage() === expectedBlast), `boss HP ${bossHp} blast uses max HP minus its phase remainder`);
      }
    } finally {
      Math.random = originalRandomForAdds;
    }
    player.getArea().leave(player, false);
    boss = null;
    cycle += 100;
    queued.length = 0;
    playerMessages.length = 0;
    let dialogueActive = true;
    player.getDialogueManager = () => ({ isActive: () => dialogueActive });
    handlers.custom.get('npc-dialogue:action').at(-1)({ player, stepId: 'xfnkES', handled: false });
    const introArea = player.getArea();
    const introStart = cycle;
    for (let offset = 1; offset <= 30; offset++) {
      cycle = introStart + offset;
      introArea.process(boss);
    }
    assert.equal(queued.length, 0, 'Seren cannot damage the player while her introduction is open');
    assert.ok(!playerMessages.some(message => message.includes('teleports you beside')), 'specials wait for the introduction too');
    dialogueActive = false;
    for (let offset = 31; offset <= 42; offset++) {
      cycle = introStart + offset;
      introArea.process(boss);
    }
    assert.ok(playerMessages.some(message => message.includes('teleports you beside')), 'closing the introduction starts the ordinary encounter timer');
    queued.length = 0;
    const messagesBeforeDeathTick = playerMessages.length;
    const npcsBeforeDeathTick = spawned.length;
    boss.hitpoints = 0;
    cycle = introStart + 45;
    introArea.process(boss);
    assert.equal(queued.length, 0, 'the defeated Fragment cannot land its queued melee special');
    assert.equal(playerMessages.length, messagesBeforeDeathTick, 'the defeated Fragment cannot start another special');
    assert.equal(spawned.length, npcsBeforeDeathTick, 'the defeated Fragment cannot spawn new echoes or beams');
  } finally {
    api.core.World.getProcessCycle = originalCycle;
    runtime.startTranscript = originalStartTranscript;
  }
});

test('Song of the Elves resumes the earned Fragment outro after reconnect', () => {
  const { api, handlers } = mockApi();
  const runtime = require('../plugins/quests/QuestRuntime');
  const originalStartTranscript = runtime.startTranscript;
  const transcripts = [];
  runtime.startTranscript = (...args) => { transcripts.push(args.slice(1)); return true; };
  try {
    require('../plugins/quests/quests/SongOfTheElves.Quest')(api);
    const quest = runtime.getRegisteredQuests().filter(entry => entry.key === 'song_of_the_elves').at(-1);
    const attributes = new Map([
      ['quest.song_of_the_elves.late-chapter', 19],
      ['quest.song_of_the_elves.fragment-defeated', true],
    ]);
    let dialogueActive = false;
    const player = {
      getAttribute: key => attributes.get(key),
      setAttribute: (key, value) => attributes.set(key, value),
      getPacketSender: () => new Proxy({}, { get: () => () => {} }),
      getDialogueManager: () => ({ isActive: () => dialogueActive }),
      moveTo() {},
    };
    quest.setStage(player, 190);
    handlers.playerLogin.at(-1)({ player });
    assert.equal(transcripts.length, 1);
    assert.equal(transcripts[0][3], 'the-fragment-of-seren-the-fragment-defeated');
    dialogueActive = true;
    handlers.playerLogin.at(-1)({ player });
    assert.equal(transcripts.length, 1, 'an active dialogue is not duplicated on a repeated login hook');
    dialogueActive = false;
    attributes.set('quest.song_of_the_elves.late-chapter', 20);
    handlers.playerLogin.at(-1)({ player });
    assert.equal(transcripts.length, 2, 'the gate farewell resumes when the saved chapter advances past the Iorwerth outro');
    assert.equal(transcripts[1][3], 'the-war-s-end-arianwyn-atones');
  } finally {
    runtime.startTranscript = originalStartTranscript;
  }
});

test('Song of the Elves chains the city-gate farewell into Baxtorian’s final talk', () => {
  const { api, handlers } = mockApi();
  const runtime = require('../plugins/quests/QuestRuntime');
  const originalStartTranscript = runtime.startTranscript;
  const transcripts = [];
  const spawned = [];
  const removed = [];
  api.spawnNpc = definition => {
    const npc = { ...definition, isRegistered: () => !npc.removed };
    spawned.push(npc);
    return npc;
  };
  api.removeNpc = npc => { npc.removed = true; removed.push(npc); };
  runtime.startTranscript = (...args) => { transcripts.push(args.at(-1)); return true; };
  try {
    require('../plugins/quests/quests/SongOfTheElves.Quest')(api);
    const quest = runtime.getRegisteredQuests().filter(entry => entry.key === 'song_of_the_elves').at(-1);
    const attributes = new Map([
      ['quest.song_of_the_elves.late-chapter', 19],
      ['quest.song_of_the_elves.fragment-defeated', true],
    ]);
    const player = {
      getAttribute: key => attributes.get(key),
      setAttribute: (key, value) => attributes.set(key, value),
      getInventory: () => ({ getFreeSlots: () => 10, getAmount: () => 0, adds() {} }),
      getPacketSender: () => new Proxy({}, { get: () => () => {} }),
      getDialogueManager: () => ({ isActive: () => false }),
      moveTo(location) { this.location = location; },
      sendMessage() {},
    };
    quest.setStage(player, 190);
    const action = { player, stepId: 'yR9ETJ', handled: false };
    handlers.custom.get('npc-dialogue:action').at(-1)(action);
    assert.equal(quest.getStage(player), 190, 'the cache quest stage stays at its pre-completion value during the finale');
    assert.equal(attributes.get('quest.song_of_the_elves.late-chapter'), 20);
    assert.deepEqual([player.location.getX(), player.location.getY(), player.location.getZ()], [2241, 3266, 0]);
    assert.equal(action.handled, true);
    assert.equal(action.steps[1].speaker, 'Arianwyn', 'the Wiki Arianwyn farewell follows the Iorwerth aftermath');
    const baxtorianTalk = handlers.npcInteractions.get('Baxtorian')['Talk-to'];
    assert.equal(baxtorianTalk({ player, npcId: api.core.NpcIdentifiers.BAXTORIAN,
      definition: { getName: () => 'Baxtorian' } }), false,
    'Baxtorian cannot skip the unfinished Arianwyn farewell');
    const prematureEnd = { player, stepId: 'W-ainS', handled: false };
    handlers.custom.get('npc-dialogue:action').at(-1)(prematureEnd);
    assert.equal(prematureEnd.handled, true);
    assert.equal(quest.isComplete(player), false, 'the quest cannot complete before the final farewell');
    const farewell = { player, text: 'And I you. Farewell friend.' };
    handlers.custom.get('npc-dialogue:line').find(h=>h.name==='finishWarEndArianwynLine')(farewell);
    assert.equal(typeof farewell.after, 'function');
    farewell.after();
    assert.equal(attributes.get('quest.song_of_the_elves.war-end-arianwyn-done'), true);
    assert.ok(removed.some(npc => npc.id === api.core.NpcIdentifiers.ARIANWYN_6));
    const baxtorian = spawned.find(npc => npc.id === api.core.NpcIdentifiers.BAXTORIAN);
    assert.ok(baxtorian?.ownerOnly, 'Baxtorian is available only to this quest owner at the gate');
    baxtorianTalk({ player, npcId: api.core.NpcIdentifiers.BAXTORIAN,
      definition: { getName: () => 'Baxtorian' }, npc: baxtorian });
    assert.equal(transcripts.at(-1), 'the-war-s-end-prifddinas-reformed');
    const actorCountAfterFarewell = spawned.length;
    quest.setStage(player, quest.completionValue);
    handlers.playerLogin.at(-1)({ player });
    assert.equal(spawned.length, actorCountAfterFarewell, 'completed quest logins do not spawn duplicate finale actors');
  } finally {
    runtime.startTranscript = originalStartTranscript;
  }
});

