  const board={player,definition:{getName:()=> 'Log raft'},option:'Board',location:{x:2509,y:3493,z:0}};assert.equal(handlers.objects.some(h=>h(board)===true),true);assert.deepEqual([at.getX(),at.getY()],[2512,3480]);
