  assert.equal(rope(crossing),true);assert.deepEqual([at.getX(),at.getY()],[2513,3468]);crossing={...crossing,objectId:api.core.ObjectIdentifiers.DEAD_TREE_15,location:{x:2512,y:3465,z:0}};assert.equal(rope(crossing),true);assert.deepEqual([at.getX(),at.getY()],[2511,3463]);
