test('Song of the Elves native progress follows library seals and later source stages', () => {
  const { api } = mockApi();
  require('../plugins/quests/quests/SongOfTheElves.Quest')(api);
  const quest = require('../plugins/quests/QuestRuntime').getRegisteredQuests()
    .filter(entry => entry.key === 'song_of_the_elves').at(-1);
  const attrs = new Map();
  let location = new api.core.Location(2353, 3172, 0);
  const player = { getAttribute: key => attrs.get(key), getLocation: () => location,
    getInventory: () => ({ getAmount: id => id === api.core.ItemIdentifiers.ORB_OF_LIGHT_5 && attrs.get('orb-held') ? 1 : 0 }) };
  const progress = (stage, key, value) => {
    if (value === undefined) attrs.delete(key);
    else attrs.set(key, value);
    return quest.varbitValue(stage, player);
  };
  const seals = 'quest.song_of_the_elves.library-seals';
  assert.equal(progress(130, seals, 0), 90, 'the guide is offered before entering');
  location = new api.core.Location(2623, 6144, 0);
  assert.equal(quest.varbitValue(130, player), 92, 'entry precedes the Forgotten memory');
  assert.equal(progress(130, seals, 1), 94, 'the Forgotten memory starts Ithell');
  assert.equal(progress(130, 'quest.song_of_the_elves.library-mirrors', 13), 94);
  assert.equal(progress(130, 'quest.song_of_the_elves.library-puzzle', '0:13'), 95,
    'the completed beam precedes touching the seal');
  assert.equal(progress(130, seals, 3), 96, 'touching Ithell starts Cadarn');
  assert.equal(progress(130, 'quest.song_of_the_elves.library-mirrors', undefined), 96);
  progress(130, 'quest.song_of_the_elves.library-puzzle', '1:0');
  assert.equal(quest.varbitValue(130, player), 96);
  assert.equal(progress(130, 'quest.song_of_the_elves.library-puzzle', '1:8'), 97);
  assert.equal(progress(130, seals, 511), 110);
  assert.equal(quest.varbitValue(140, player), 110);
  assert.equal(quest.varbitValue(150, player), 112);
  assert.equal(progress(150, 'quest.song_of_the_elves.recruited-elders', 2), 116);
  assert.equal(progress(150, 'quest.song_of_the_elves.recruited-elders', 1), 118);
  assert.equal(progress(150, 'quest.song_of_the_elves.recruited-elders', 3), 120);
  attrs.set('orb-held', true);
  assert.equal(quest.varbitValue(150, player), 130, 'carrying the recovered Orb before starting Ysgawyn tracking gets native progress130');
  assert.equal(progress(150, 'quest.song_of_the_elves.ysgawyn-track-step', 0), 134, 'Elena starts the trail after the Orb is returned');
  assert.equal(progress(150, 'quest.song_of_the_elves.ysgawyn-track-step', 6), 138, 'following clues advances native progress');
  assert.equal(progress(150, 'quest.song_of_the_elves.ysgawyn-track-step', 7), 140, 'reaching Ysgawyn completes the trail progress');
  assert.equal(quest.varbitValue(160, player), 142);
  assert.equal(progress(160, 'quest.song_of_the_elves.lletya-children', { eoin: true }), 144);
  assert.equal(progress(160, 'quest.song_of_the_elves.lletya-children', { eoin: true, iona: true }), 146);
  assert.equal(progress(160, 'quest.song_of_the_elves.lletya-traitor-revealed', true), 150);
  assert.equal(progress(160, 'quest.song_of_the_elves.lletya-arianwyn-confronted', true), 152);
  assert.equal(quest.varbitValue(170, player), 160);
  assert.equal(progress(170, 'quest.song_of_the_elves.recruited-elders', 12), 164);
  const holes = 'quest.song_of_the_elves.camp-holes';
  for (let count = 0; count <= 7; count++) {
    const mask = (1 << count) - 1;
    assert.equal(progress(180, holes, mask), 166 + count * 2,
      `the camp native progress tracks ${count} of seven filled holes`);
  }
  assert.equal(progress(190, holes, 127), 180, 'the ready camp waits at the native siege step');
  assert.equal(progress(190, 'quest.song_of_the_elves.camp-defense', 400), 182,
    'the active four-minute defense uses its own native step');
  progress(190, 'quest.song_of_the_elves.late-chapter', 18);
  assert.equal(quest.varbitValue(190, player), 182,
    'legacy saves that retain late chapter 18 still show the active siege');
  assert.equal(progress(190, 'quest.song_of_the_elves.camp-defense-complete', true), 184,
    'the completed defense advances before the fragment chapter');
  assert.equal(quest.varbitValue(190, player), 184,
    'late chapter 18 keeps the completed camp step');
  progress(190, 'quest.song_of_the_elves.camp-defense', undefined);
  progress(190, 'quest.song_of_the_elves.camp-defense-complete', undefined);
  progress(190, holes, undefined);
  assert.equal(progress(190, 'quest.song_of_the_elves.late-chapter', 19), 186);
  assert.equal(progress(190, 'quest.song_of_the_elves.fragment-defeated', true), 188);
  assert.equal(progress(190, 'quest.song_of_the_elves.late-chapter', 20), 190);
  assert.equal(progress(190, 'quest.song_of_the_elves.war-end-arianwyn-done', true), 192);
});

